INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('33', 'mi', 'Mikha', 5, 5, '(5-4) dan dia menjadi damai sejahtera. Apabila Asyur masuk ke negeri kita dan apabila ia menginjak tanah kita, maka kita akan membangkitkan melawan dia tujuh gembala, bahkan delapan pemimpin manusia.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 6, '(5-5) Mereka itu akan mencukur negeri Asyur dengan pedang dan negeri Nimrod dengan pedang terhunus; mereka akan melepaskan kita dari Asyur, apabila ia ini masuk ke negeri kita dan menginjak daerah kita.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 7, '(5-6) Maka sisa-sisa Yakub akan ada di tengah-tengah banyak bangsa seperti embun dari pada TUHAN seperti dirus hujan ke atas tumbuh-tumbuhan yang tidak menanti-nantikan orang dan tidak mengharap-harapkan anak manusia.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 8, '(5-7) Maka sisa-sisa Yakub akan ada di antara suku-suku bangsa, di tengah-tengah banyak bangsa seperti singa di antara binatang-binatang hutan, seperti singa muda di antara kawanan kambing domba: ke manapun ia pergi, maka ia membanting dan menerkam, sedang tidak ada yang melepaskan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 9, '(5-8) Tanganmu akan diangkat melawan para lawanmu, dan semua musuhmu akan dilenyapkan!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 10, '(5-9) Maka akan terjadi pada waktu itu, demikianlah firman TUHAN, Aku akan melenyapkan kudamu dari tengah-tengahmu dan akan membinasakan keretamu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 11, '(5-10) Aku akan melenyapkan kota-kota negerimu dan akan meruntuhkan segala kubumu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 12, '(5-11) Aku akan melenyapkan alat-alat sihir dari tanganmu, dan tukang-tukang peramal tidak akan ada lagi padamu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 13, '(5-12) Aku akan melenyapkan patung-patungmu dan tugu-tugu berhalamu dari tengah-tengahmu, maka engkau tidak lagi akan sujud menyembah kepada buatan tanganmu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 14, '(5-13) Aku akan menyentakkan tiang-tiang berhalamu dari tengah-tengahmu dan akan memunahkan berhalamu;', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 15, '(5-14) Aku akan membalas dendam dengan murka dan kehangatan amarah, kepada bangsa-bangsa yang tidak mau mendengarkan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 1, 'Baiklah dengar firman yang diucapkan TUHAN: Bangkitlah, lancarkanlah pengaduan di depan gunung-gunung, dan biarlah bukit-bukit mendengar suaramu!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 2, 'Dengarlah, hai gunung-gunung, pengaduan TUHAN, dan pasanglah telinga, hai dasar-dasar bumi! Sebab TUHAN mempunyai pengaduan terhadap umat-Nya, dan Ia beperkara dengan Israel.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 3, '"Umat-Ku, apakah yang telah Kulakukan kepadamu? Dengan apakah engkau telah Kulelahkan? Jawablah Aku!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 4, 'Sebab Aku telah menuntun engkau keluar dari tanah Mesir dan telah membebaskan engkau dari rumah perbudakan dan telah mengutus Musa dan Harun dan Miryam sebagai penganjurmu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 5, 'Umat-Ku, baiklah ingat apa yang dirancangkan oleh Balak, raja Moab, dan apa yang dijawab kepadanya oleh Bileam bin Beor dan apa yang telah terjadi dari Sitim sampai ke Gilgal, supaya engkau mengakui perbuatan-perbuatan keadilan dari TUHAN."', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 6, '"Dengan apakah aku akan pergi menghadap TUHAN dan tunduk menyembah kepada Allah yang di tempat tinggi? Akan pergikah aku menghadap Dia dengan korban bakaran, dengan anak lembu berumur setahun?', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 7, 'Berkenankah TUHAN kepada ribuan domba jantan, kepada puluhan ribu curahan minyak? Akan kupersembahkankah anak sulungku karena pelanggaranku dan buah kandunganku karena dosaku sendiri?"', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 8, '"Hai manusia, telah diberitahukan kepadamu apa yang baik. Dan apakah yang dituntut TUHAN dari padamu: selain berlaku adil, mencintai kesetiaan, dan hidup dengan rendah hati di hadapan Allahmu?"', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 9, 'Dengarlah, TUHAN berseru kepada kota: ?adalah bijaksana untuk takut kepada nama-Nya?:"Dengarlah, hai suku bangsa dan orang kota!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 10, 'Masakan Aku melupakan harta benda kefasikan di rumah orang fasik dan takaran efa yang kurang dan terkutuk itu?', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 11, 'Masakan Aku membiarkan tidak dihukum orang yang membawa neraca palsu atau pundi-pundi berisi batu timbangan tipu?', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 12, 'Orang-orang kaya di kota itu melakukan banyak kekerasan, penduduknya berkata dusta dan lidah dalam mulut mereka adalah penipu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 13, 'Maka Akupun mulai memukul engkau, menanduskan engkau oleh karena dosamu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 14, 'Engkau ini akan makan, tetapi tidak menjadi kenyang, dan perutmu tetap mengamuk karena lapar; engkau akan menyingkirkan sesuatu, tetapi tidak dapat menyelamatkannya, dan apa yang dapat kauselamatkan, akan Kuserahkan kepada pedang.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 15, 'Engkau ini akan menabur, tetapi tidak menuai, engkau ini akan mengirik buah zaitun, tetapi tidak berurap dengan minyaknya; juga mengirik buah anggur, tetapi tidak meminum anggurnya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 6, 16, 'Engkau telah berpaut kepada ketetapan-ketetapan Omri dan kepada segala perbuatan keluarga Ahab, dan engkau telah bertindak menurut rancangan mereka, sehingga Aku membuat engkau menjadi ketandusan dan pendudukmu menjadi sasaran suitan; demikianlah kamu akan menanggung pencelaan dari pihak bangsa-bangsa."', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 1, 'Celaka aku! Sebab keadaanku seperti pada pengumpulan buah-buahan musim kemarau, seperti pada pemetikan susulan buah anggur: tidak ada buah anggur untuk dimakan, atau buah ara yang kusukai.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 2, 'Orang saleh sudah hilang dari negeri, dan tiada lagi orang jujur di antara manusia. Mereka semuanya mengincar darah, yang seorang mencoba menangkap yang lain dengan jaring.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 3, 'Tangan mereka sudah cekatan berbuat jahat; pemuka menuntut, hakim dapat disuap; pembesar memberi putusan sekehendaknya, dan hukum, mereka putar balikkan!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 4, 'Orang yang terbaik di antara mereka adalah seperti tumbuhan duri, yang paling jujur di antara mereka seperti pagar duri; hari bagi pengintai-pengintaimu, hari penghukumanmu, telah datang, sekarang akan mulai kegemparan di antara mereka!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 5, 'Janganlah percaya kepada teman, janganlah mengandalkan diri kepada kawan! Jagalah pintu mulutmu terhadap perempuan yang berbaring di pangkuanmu!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 6, 'Sebab anak laki-laki menghina ayahnya, anak perempuan bangkit melawan ibunya, menantu perempuan melawan ibu mertuanya; musuh orang ialah orang-orang seisi rumahnya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 7, 'Tetapi aku ini akan menunggu-nunggu TUHAN, akan mengharapkan Allah yang menyelamatkan aku; Allahku akan mendengarkan aku!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 8, 'Janganlah bersukacita atas aku, hai musuhku! Sekalipun aku jatuh, aku akan bangun pula, sekalipun aku duduk dalam gelap, TUHAN akan menjadi terangku.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 9, 'Aku akan memikul kemarahan TUHAN, sebab aku telah berdosa kepada-Nya, sampai Ia memperjuangkan perkaraku dan memberi keadilan kepadaku, membawa aku ke dalam terang, sehingga aku mengalami keadilan-Nya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 10, 'Musuhku akan melihatnya dan dengan malu ia akan menutupi mukanya, dia yang berkata kepadaku: "Di mana TUHAN, Allahmu?" Mataku akan memandangi dia; sekarang ia diinjak-injak seperti lumpur di jalan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 11, 'Akan datang suatu hari bahwa pagar tembokmu akan dibangun kembali; pada hari itulah perbatasanmu akan diperluas.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 12, 'Pada hari itu orang akan menghadap engkau dari Asyur sampai Mesir, dari Mesir sampai sungai Efrat, dari laut ke laut, dari gunung ke gunung.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 13, 'Tetapi bumi akan menjadi tandus oleh karena penduduknya, sebagai akibat perbuatan mereka.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 14, 'Gembalakanlah umat-Mu dengan tongkat-Mu, kambing domba milik-Mu sendiri, yang terpencil mendiami rimba di tengah-tengah kebun buah-buahan. Biarlah mereka makan rumput di Basan dan di Gilead seperti pada zaman dahulu kala.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 15, 'Seperti pada waktu Engkau keluar dari Mesir, perlihatkanlah kepada kami keajaiban-keajaiban!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 16, 'Biarlah bangsa-bangsa melihatnya dan merasa malu atas segala keperkasaan mereka; biarlah mereka menutup mulutnya dengan tangan, dan telinganya menjadi tuli.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 17, 'Biarlah mereka menjilat debu seperti ular, seperti binatang menjalar di bumi; biarlah mereka keluar dengan gemetar dari kubunya, dan datang kepada TUHAN, Allah kami, dengan gentar, dengan takut kepada-Mu!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 18, 'Siapakah Allah seperti Engkau yang mengampuni dosa, dan yang memaafkan pelanggaran dari sisa-sisa milik-Nya sendiri; yang tidak bertahan dalam murka-Nya untuk seterusnya, melainkan berkenan kepada kasih setia?', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 19, 'Biarlah Ia kembali menyayangi kita, menghapuskan kesalahan-kesalahan kita dan melemparkan segala dosa kita ke dalam tubir-tubir laut.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 7, 20, 'Kiranya Engkau menunjukkan setia-Mu kepada Yakub dan kasih-Mu kepada Abraham seperti yang telah Kaujanjikan dengan bersumpah kepada nenek moyang kami sejak zaman purbakala!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 1, 'Ucapan ilahi tentang Niniwe. Kitab penglihatan Nahum, orang Elkosh.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 2, 'TUHAN itu Allah yang cemburu dan pembalas, TUHAN itu pembalas dan penuh kehangatan amarah. TUHAN itu pembalas kepada para lawan-Nya dan pendendam kepada para musuh-Nya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 3, 'TUHAN itu panjang sabar dan besar kuasa, tetapi Ia tidak sekali-kali membebaskan dari hukuman orang yang bersalah. Ia berjalan dalam puting beliung dan badai, dan awan adalah debu kaki-Nya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 4, 'Ia menghardik laut dan mengeringkannya, dan segala sungai dijadikan-Nya kering. Basan dan Karmel menjadi merana dan kembang Libanon menjadi layu.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 5, 'Gunung-gunung gemetar terhadap Dia, dan bukit-bukit mencair. Bumi menjadi sunyi sepi di hadapan-Nya, dunia serta seluruh penduduknya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 6, 'Siapakah yang tahan berdiri menghadapi geram-Nya? Dan siapakah yang tahan tegak terhadap murka-Nya yang bernyala-nyala? Kehangatan amarah-Nya tercurah seperti api, dan gunung-gunung batu menjadi roboh di hadapan-Nya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 7, 'TUHAN itu baik; Ia adalah tempat pengungsian pada waktu kesusahan; Ia mengenal orang-orang yang berlindung kepada-Nya', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 8, 'dan menyeberangkan mereka pada waktu banjir. Ia menghabisi sama sekali orang-orang yang bangkit melawan Dia, dan musuh-Nya dihalau-Nya ke dalam gelap.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 9, 'Apakah maksudmu menentang TUHAN? Ia akan menghabisi sama sekali; kesengsaraan tidak akan timbul dua kali!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 10, 'Sebab merekapun akan lenyap seperti duri yang berjalin-jalin, dimakan habis seperti jerami kering.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 11, 'Bukankah dari padamu muncul orang yang merancang kejahatan terhadap TUHAN, orang yang memberi nasihat dursila?', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 12, 'Beginilah firman TUHAN: "Sekalipun mereka utuh dan begitu banyak jumlahnya, tetapi mereka akan hilang terbabat dan mati binasa; sekalipun Aku telah merendahkan engkau, tetapi Aku tidak akan merendahkan engkau lagi.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 13, 'Sekarang, Aku akan mematahkan gandarnya yang memberati engkau, dan akan memutuskan belenggu-belenggu yang mengikat engkau."', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 14, 'Terhadap engkau, inilah perintah TUHAN: "Tidak akan ada lagi keturunan dengan namamu. Dari rumah allahmu Aku akan melenyapkan patung pahatan dan patung tuangan; kuburmu akan Kusediakan, sebab engkau hina."', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 1, 15, 'Lihatlah! Di atas gunung-gunung berjalan orang yang membawa berita, yang mengabarkan berita damai sejahtera. Rayakanlah hari rayamu, hai Yehuda, bayarlah nazarmu! Sebab tidak akan datang lagi orang dursila menyerang engkau; ia telah dilenyapkan sama sekali!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 1, 'Pembongkar maju terhadap engkau; adakan penjagaan di benteng, mengintailah di jalan, ikatlah pinggangmu teguh-teguh, kumpulkanlah segala kekuatan!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 2, 'Sungguh, TUHAN memulihkan kebanggaan Yakub, seperti kebanggaan Israel; sebab perusak telah merusakkannya dan telah membinasakan carang-carangnya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 3, 'Perisai para pahlawannya berwarna merah, prajuritnya berpakaian kirmizi; kereta berkilat-kilat seperti api suluh pada hari ia melengkapinya, dan kuda-kuda penuh gelisah.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 4, 'Kereta melaju galak di jalan, kejar-mengejar di lapangan; kelihatannya seperti suluh, berpacu seperti kilat.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 5, 'Pasukan-pasukan istimewa dikerahkan, mereka tersandung jatuh di waktu berjalan maju; mereka lari terburu-buru ke arah tembok kota, sedang alat pendobrak sudah ditegakkan.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 6, 'Pintu-pintu di sungai-sungai telah dibuka, dan istana menjadi gempar.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 7, 'Permaisuri dibawa ke luar dan ditelanjangi dan dayang-dayangnya mengerang, mengaduh seperti suara merpati sambil memukul-mukul dada.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 8, 'Niniwe sendiri seperti kolam air yang airnya mengalir ke luar. "Berhenti! Berhenti!" teriak orang, tetapi tidak ada yang berpaling.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 9, 'Jarahlah perak, jarahlah emas! Sebab tidak berkesudahan persediaan harta benda, kelimpahan segala barang yang indah-indah!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 10, 'Ketandusan, penandusan dan penindasan! Hati menjadi tawar dan lutut goyah! Segenap pinggang gemetar, dan muka sekalian orang menjadi pucat pasi.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 11, 'Di mana gerangan persembunyian singa dan gua singa-singa muda, tempat singa pulang pergi, tempat anak singa, di mana tidak ada yang mengganggunya?', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 12, 'Biasanya singa itu menerkam supaya cukup makan anak-anaknya, mencekik mangsa bagi betina-betinanya, dan memenuhi liangnya dengan mangsa dan persembunyiannya dengan terkaman.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 2, 13, 'Lihat, Aku akan menjadi lawanmu, demikianlah firman TUHAN semesta alam, Aku akan membakar keretamu menjadi asap, dan pedang akan memakan habis singa mudamu; Aku akan melenyapkan mangsamu dari atas bumi, dan suara utusan-utusanmu tidak akan terdengar lagi.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 1, 'Celakalah kota penumpah darah itu! Seluruhnya dusta belaka, penuh dengan perampasan, dan tidak henti-hentinya penerkaman!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 2, 'Dengar, lecut cambuk dan derak-derik roda! Dengar, kuda lari menderap, dan kereta meloncat-loncat!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 3, 'Pasukan berkuda menyerang, pedang bernyala-nyala dan tombak berkilat-kilat! Banyak yang mati terbunuh dan bangkai bertimbun-timbun! Tidak habis-habisnya mayat-mayat, orang tersandung jatuh pada mayat-mayat!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 4, 'Semuanya karena banyaknya persundalan si perempuan sundal, yang cantik parasnya dan ahli dalam sihir, yang memperdayakan bangsa-bangsa dengan persundalannya dan kaum-kaum dengan sihirnya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 5, 'Lihat, Aku akan menjadi lawanmu, demikianlah firman TUHAN semesta alam; Aku akan mengangkat ujung kainmu sampai ke mukamu dan akan memperlihatkan auratmu kepada bangsa-bangsa dan kemaluanmu kepada kerajaan-kerajaan.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 6, 'Aku akan melemparkan barang keji ke atasmu, akan menghina engkau dan akan membuat engkau menjadi tontonan.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 7, 'Maka semua orang yang melihat engkau akan lari meninggalkan engkau serta berkata: "Niniwe sudah rusak! Siapakah yang meratapi dia? Dari manakah aku akan mencari penghibur-penghibur untuk dia?"', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 8, 'Adakah engkau lebih baik dari Tebe, kota dewa Amon, yang letaknya di sungai Nil, dengan air sekelilingnya, yang tembok kotanya adalah laut, dan bentengnya adalah air?', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 9, 'Etiopia adalah kekuatannya, juga Mesir, dengan tidak terbatas; Put dan orang-orang Libia adalah pembantunya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 10, 'Tetapi dia sendiripun terpaksa pergi ke dalam pembuangan, terpaksa masuk ke dalam tawanan. Bayi-bayinyapun diremukkan di ujung segala jalan; tentang semua orangnya yang dihormati dibuang undi, dan semua pembesarnya dibelenggu dengan rantai.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 11, 'Engkaupun akan menjadi mabuk, akan menjadi tidak berdaya; engkaupun akan mencari tempat perlindungan terhadap musuh.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 12, 'Segala kubumu adalah seperti pohon ara dengan buah ara yang masak duluan; jika diayunkan, maka jatuhlah buahnya ke dalam mulut orang yang hendak memakannya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 13, 'Sesungguhnya, laskar yang di tengah-tengahmu itu adalah perempuan-perempua pintu-pintu gerbang negerimu terbuka lebar-lebar untuk musuhmu; api telah memakan habis palang pintumu.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 14, 'Timbalah air menghadapi pengepungan, perkuatlah kubu-kubumu! Pijaklah lumpur, injaklah tanah liat, peganglah acuan batu bata!', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 15, 'Di sana api akan memakan engkau habis, pedang akan membabat engkau, akan memakan engkau seperti belalang pelompat. Sekalipun engkau berjumlah besar seperti belalang pelompat, berjumlah besar seperti belalang pindahan,', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 16, 'sekalipun kauperbanyak orang-orang dagangmu lebih dari bintang-bintang di langit, seperti belalang pelompat mereka mengembangkan sayap dan terbang menghilang.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 17, 'Sekalipun para penjagamu seperti belalang pindahan dan para pegawaimu seperti kawanan belalang, yang hinggap pada tembok-tembok pada waktu dingin, namun jika matahari terbit, mereka lari menghilang, tidak ketahuan tempatnya.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 18, 'Celaka! Alangkah terlelapnya para gembalamu, hai raja negeri Asyur! Para pemukamu tertidur, laskarmu berserak-serak di gunung-gunung, dan tidak ada yang mengumpulkan.', 'id', 'TB'),
  ('34', 'nah', 'Nahum', 3, 19, 'Tiada pengobatan untuk cederamu, lukamu tidak tersembuhkan. Semua orang yang mendengar tentang engkau bertepuk tangan karena engkau; sebab kepada siapakah tidak tertimpa perbuatan jahatmu terus-menerus?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 1, 'Ucapan ilahi dalam penglihatan nabi Habakuk.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 2, 'Berapa lama lagi, TUHAN, aku berteriak, tetapi tidak Kaudengar, aku berseru kepada-Mu: "Penindasan!" tetapi tidak Kautolong?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 3, 'Mengapa Engkau memperlihatkan kepadaku kejahatan, sehingga aku memandang kelaliman? Ya, aniaya dan kekerasan ada di depan mataku; perbantahan dan pertikaian terjadi.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 4, 'Itulah sebabnya hukum kehilangan kekuatannya dan tidak pernah muncul keadilan, sebab orang fasik mengepung orang benar; itulah sebabnya keadilan muncul terbalik.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 5, 'Lihatlah di antara bangsa-bangsa dan perhatikanlah, jadilah heran dan tercengang-cengang, sebab Aku melakukan suatu pekerjaan dalam zamanmu yang tidak akan kamu percayai, jika diceriterakan.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 6, 'Sebab, sesungguhnya, Akulah yang membangkitkan orang Kasdim, bangsa yang garang dan tangkas itu, yang melintasi lintang bujur bumi untuk menduduki tempat kediaman, yang bukan kepunyaan mereka.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 7, 'Bangsa itu dahsyat dan menakutkan; keadilannya dan keluhurannya berasal dari padanya sendiri.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 8, 'Kudanya lebih cepat dari pada macan tutul, dan lebih ganas dari pada serigala pada waktu malam; pasukan berkudanya datang menderap, dari jauh mereka datang, terbang seperti rajawali yang menyambar mangsa.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 9, 'Seluruh bangsa itu datang untuk melakukan kekerasan, serbuan pasukan depannya seperti angin timur, dan mereka mengumpulkan tawanan seperti banyaknya pasir.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 10, 'Raja-raja dicemoohkannya dan penguasa-penguasa menjadi tertawaannya. Ditertawakannya tiap tempat berkubu, ditimbunkannya tanah dan direbutnya tempat itu.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 11, 'Maka berlarilah mereka, seperti angin dan bergerak terus; demikianlah mereka bersalah dengan mendewakan kekuatannya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 12, 'Bukankah Engkau, ya TUHAN, dari dahulu Allahku, Yang Mahakudus? Tidak akan mati kami. Ya TUHAN, telah Kautetapkan dia untuk menghukumkan; ya Gunung Batu, telah Kautentukan dia untuk menyiksa.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 13, 'Mata-Mu terlalu suci untuk melihat kejahatan dan Engkau tidak dapat memandang kelaliman. Mengapa Engkau memandangi orang-orang yang berbuat khianat itu dan Engkau berdiam diri, apabila orang fasik menelan orang yang lebih benar dari dia?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 14, 'Engkau menjadikan manusia itu seperti ikan di laut, seperti binatang-binatang melata yang tidak ada pemerintahnya?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 15, 'Semuanya mereka ditariknya ke atas dengan kail, ditangkap dengan pukatnya dan dikumpulkan dengan payangnya; itulah sebabnya ia bersukaria dan bersorak-sorai.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 16, 'Itulah sebabnya dipersembahkannya korban untuk pukatnya dan dibakarnya korban untuk payangnya; sebab oleh karena alat-alat itu pendapatannya mewah dan rezekinya berlimpah-limpah.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 1, 17, 'Sebab itukah ia selalu menghunus pedangnya dan membunuh bangsa-bangsa dengan tidak kenal belas kasihan?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 1, 'Aku mau berdiri di tempat pengintaianku dan berdiri tegak di menara, aku mau meninjau dan menantikan apa yang akan difirmankan-Nya kepadaku, dan apa yang akan dijawab-Nya atas pengaduanku.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 2, 'Lalu TUHAN menjawab aku, demikian: "Tuliskanlah penglihatan itu dan ukirkanlah itu pada loh-loh, supaya orang sambil lalu dapat membacanya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 3, 'Sebab penglihatan itu masih menanti saatnya, tetapi ia bersegera menuju kesudahannya dengan tidak menipu; apabila berlambat-lambat, nantikanlah itu, sebab itu sungguh-sungguh akan datang dan tidak akan bertangguh.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 4, 'Sesungguhnya, orang yang membusungkan dada, tidak lurus hatinya, tetapi orang yang benar itu akan hidup oleh percayanya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 5, 'Orang sombong dan khianat dia yang melagak, tetapi ia tidak akan tetap ada; ia mengangakan mulutnya seperti dunia orang mati dan tidak kenyang-kenyang seperti maut, sehingga segala suku bangsa dikumpulkannya dan segala bangsa dihimpunkannya."', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 6, 'Bukankah sekalian itu akan melontarkan peribahasa mengatai dia, dan nyanyian olok-olok serta sindiran ini: Celakalah orang yang menggaruk bagi dirinya apa yang bukan miliknya?berapa lama lagi? ?dan yang memuati dirinya dengan barang gadaian.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 7, 'Bukankah akan bangkit dengan sekonyong-konyong mereka yang menggigit engkau, dan akan terjaga mereka yang mengejutkan engkau, sehingga engkau menjadi barang rampasan bagi mereka?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 8, 'Karena engkau telah menjarah banyak suku bangsa, maka bangsa-bangsa yang tertinggal akan menjarah engkau, karena darah manusia yang tertumpah itu dan karena kekerasan terhadap negeri, kota dan seluruh penduduknya itu.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 9, 'Celakalah orang yang mengambil laba yang tidak halal untuk keperluan rumahnya, untuk menempatkan sarangnya di tempat yang tinggi, dengan maksud melepaskan dirinya dari genggaman malapetaka!', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 10, 'Engkau telah merancangkan cela ke atas rumahmu, ketika engkau bermaksud untuk menghabisi banyak bangsa; dengan demikian engkau telah berdosa terhadap dirimu sendiri.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 11, 'Sebab batu berseru-seru dari tembok, dan balok menjawabnya dari rangka rumah.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 12, 'Celakalah orang yang mendirikan kota di atas darah dan meletakkan dasar benteng di atas ketidakadilan.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 13, 'Sesungguhnya, bukankah dari TUHAN semesta alam asalnya, bahwa bangsa-bangsa bersusah-susah untuk api dan suku-suku bangsa berlelah untuk yang sia-sia?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 14, 'Sebab bumi akan penuh dengan pengetahuan tentang kemuliaan TUHAN, seperti air yang menutupi dasar laut.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 15, 'Celakalah orang yang memberi minum sesamanya manusia bercampur amarah, bahkan memabukkan dia untuk memandang auratnya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 16, 'Telah engkau kenyangkan dirimu dengan kehinaan ganti kehormatan. Minumlah juga engkau dan terhuyung-huyunglah. Kepadamu akan beralih piala dari tangan kanan TUHAN, dan cela besar akan meliputi kemuliaanmu.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 17, 'Sebab kekerasan terhadap gunung Libanon akan menutupi engkau dan pemusnahan binatang-binatang akan mengejutkan engkau, karena darah manusia yang tertumpah itu dan karena kekerasan terhadap negeri, kota dan seluruh penduduknya itu.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 18, 'Apakah gunanya patung pahatan, yang dipahat oleh pembuatnya? Apakah gunanya patung tuangan, pengajar dusta itu? Karena pembuatnya percaya akan buatannya, padahal berhala-berhala bisu belaka yang dibuatnya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 19, 'Celakalah orang yang berkata kepada sepotong kayu: "Terjagalah!" dan kepada sebuah batu bisu: "Bangunlah!" Masakan dia itu mengajar? Memang ia bersalutkan emas dan perak, tetapi roh tidak ada sama sekali di dalamnya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 2, 20, 'Tetapi TUHAN ada di dalam bait-Nya yang kudus. Berdiam dirilah di hadapan-Nya, ya segenap bumi!', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 1, 'Doa nabi Habakuk. Menurut nada ratapan.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 2, 'TUHAN, telah kudengar kabar tentang Engkau, dan pekerjaan-Mu, ya TUHAN, kutakuti! Hidupkanlah itu dalam lintasan tahun, nyatakanlah itu dalam lintasan tahun; dalam murka ingatlah akan kasih sayang!', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 3, 'Allah datang dari negeri Teman dan Yang Mahakudus dari pegunungan Paran. Sela. Keagungan-Nya menutupi segenap langit, dan bumipun penuh dengan pujian kepada-Nya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 4, 'Ada kilauan seperti cahaya, sinar cahaya dari sisi-Nya dan di situlah terselubung kekuatan-Nya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 5, 'Mendahului-Nya berjalan penyakit sampar dan demam mengikuti jejak-Nya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 6, 'Ia berdiri, maka bumi dibuat-Nya bergoyang; Ia melihat berkeliling, maka bangsa-bangsa dibuat-Nya melompat terkejut, hancur gunung-gunung yang ada sejak purba, merendah bukit-bukit yang berabad-abad; itulah perjalanan-Nya berabad-abad.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 7, 'Aku melihat kemah-kemah orang Kusyan tertekan, kain-kain tenda tanah Midian menggetar.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 8, 'Terhadap sungai-sungaikah, ya TUHAN, terhadap sungai-sungaikah murka-Mu bangkit? Atau terhadap lautkah amarah-Mu sehingga Engkau mengendarai kuda dan kereta kemenangan-Mu?', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 9, 'Busur-Mu telah Kaubuka, telah Kauisi dengan anak panah. Sela. Engkau membelah bumi menjadi sungai-sungai;', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 10, 'melihat Engkau, gunung-gunung gemetar, air bah menderu lalu, samudera raya memperdengarkan suaranya dan mengangkat tangannya.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 11, 'Matahari, bulan berhenti di tempat kediamannya, karena cahaya anak-anak panah-Mu yang melayang laju, karena kilauan tombak-Mu yang berkilat.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 12, 'Dalam kegeraman Engkau melangkah melintasi bumi, dalam murka Engkau menggasak bangsa-bangsa.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 13, 'Engkau berjalan maju untuk menyelamatkan umat-Mu, untuk menyelamatkan orang yang Kauurapi. Engkau meremukkan bagian atas rumah orang-orang fasik dan Kaubuka dasarnya sampai batu yang penghabisan. Sela.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 14, 'Engkau menusuk dengan anak panahnya sendiri kepala lasykarnya, yang mengamuk untuk menyerakkan aku dengan sorak-sorai, seolah-olah mereka menelan orang tertindas secara tersembunyi.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 15, 'Dengan kuda-Mu, Engkau menginjak laut, timbunan air yang membuih.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 16, 'Ketika aku mendengarnya, gemetarlah hatiku, mendengar bunyinya, menggigillah bibirku; tulang-tulangku seakan-akan kemasukan sengal, dan aku gemetar di tempat aku berdiri; namun dengan tenang akan kunantikan hari kesusahan, yang akan mendatangi bangsa yang bergerombolan menyerang kami.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 17, 'Sekalipun pohon ara tidak berbunga, pohon anggur tidak berbuah, hasil pohon zaitun mengecewakan, sekalipun ladang-ladang tidak menghasilkan bahan makanan, kambing domba terhalau dari kurungan, dan tidak ada lembu sapi dalam kandang,', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 18, 'namun aku akan bersorak-sorak di dalam TUHAN, beria-ria di dalam Allah yang menyelamatkan aku.', 'id', 'TB'),
  ('35', 'hab', 'Habakuk', 3, 19, 'ALLAH Tuhanku itu kekuatanku: Ia membuat kakiku seperti kaki rusa, Ia membiarkan aku berjejak di bukit-bukitku. (Untuk pemimpin biduan. Dengan permainan kecapi).', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 1, 'Firman TUHAN yang datang kepada Zefanya bin Kusyi bin Gedalya bin Amarya bin Hizkia dalam zaman Yosia bin Amon, raja Yehuda.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 2, '"Aku akan menyapu bersih segala-galanya dari atas muka bumi, demikianlah firman TUHAN.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 3, 'Aku akan menyapu manusia dan hewan; Aku akan menyapu burung-burung di udara dan ikan-ikan di laut. Aku akan merebahkan orang-orang fasik dan akan melenyapkan manusia dari atas muka bumi, demikianlah firman TUHAN.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 4, 'Aku akan mengacungkan tangan-Ku terhadap Yehuda dan terhadap segenap penduduk Yerusalem. Aku akan melenyapkan dari tempat ini sisa-sisa Baal dan nama para imam berhala,', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 5, 'juga mereka yang sujud menyembah di atas sotoh kepada tentara langit dan mereka yang menyembah dengan bersumpah setia kepada TUHAN, namun di samping itu bersumpah demi Dewa Milkom,', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 6, 'serta mereka yang berbalik dari pada TUHAN, yang tidak mencari TUHAN dan tidak menanyakan petunjuk-Nya."', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 7, 'Berdiam dirilah di hadapan Tuhan ALLAH! Sebab hari TUHAN sudah dekat. Sungguh TUHAN telah menyediakan perjamuan korban dan telah menguduskan para undangan-Nya.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 8, '"Pada hari perjamuan korban TUHAN itu Aku akan menghukum para pemuka, para anak-anak raja dan semua orang yang memakai pakaian asing.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 9, 'Aku akan menghukum pada hari itu semua orang yang melompati ambang pintu dan memenuhi istana tuan mereka dengan kekerasan dan penipuan.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 10, 'Maka pada hari itu, demikianlah firman TUHAN, akan terdengar teriakan dari Pintu Gerbang Ikan dan ratapan dari perkampungan baru dan bunyi keruntuhan hebat dari bukit-bukit.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 11, 'Merataplah, hai penduduk perkampungan Lumpang! Sebab telah habis segenap kaum pedagang, telah lenyap segenap penimbang perak.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 12, 'Pada waktu itu Aku akan menggeledah Yerusalem dengan memakai obor dan akan menghukum orang-orang yang telah mengental seperti anggur di atas endapannya dan yang berkata dalam hatinya: TUHAN tidak berbuat baik dan tidak berbuat jahat!', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 13, 'Maka harta kekayaannya akan dirampas dan rumah-rumahnya akan menjadi sunyi sepi. Apabila mereka mendirikan rumah, mereka tidak akan mendiaminya; apabila mereka membuat kebun anggur, mereka tidak akan minum anggurnya."', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 14, 'Sudah dekat hari TUHAN yang hebat itu, sudah dekat dan datang dengan cepat sekali! Dengar, hari TUHAN pahit, pahlawanpun akan menangis.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 15, 'Hari kegemasan hari itu, hari kesusahan dan kesulitan, hari kemusnahan dan pemusnahan, hari kegelapan dan kesuraman, hari berawan dan kelam,', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 16, 'hari peniupan sangkakala dan pekik tempur terhadap kota-kota yang berkubu dan terhadap menara penjuru yang tinggi.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 17, 'Aku akan menyusahkan manusia, sehingga mereka berjalan seperti orang buta, sebab mereka telah berdosa kepada TUHAN. Darah mereka akan tercurah seperti debu dan usus mereka seperti tahi.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 1, 18, 'Mereka tidak dapat diselamatkan oleh perak atau emas mereka pada hari kegemasan TUHAN, dan seluruh bumi akan dimakan habis oleh api cemburu-Nya; sebab kebinasaan, malah kebinasaan dahsyat diadakan-Nya terhadap segenap penduduk bumi.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 1, 'Bersemangatlah dan berkumpullah, hai bangsa yang acuh tak acuh,', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 2, 'sebelum kamu dihalau seperti sekam yang tertiup, sebelum datang ke atasmu murka TUHAN yang bernyala-nyala itu, sebelum datang ke atasmu hari kemurkaan TUHAN.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 3, 'Carilah TUHAN, hai semua orang yang rendah hati di negeri, yang melakukan hukum-Nya; carilah keadilan, carilah kerendahan hati; mungkin kamu akan terlindung pada hari kemurkaan TUHAN.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 4, 'Sebab Gaza akan ditinggalkan orang dan Askelon akan menjadi sunyi; Asdod akan dihalau penduduknya pada rembang tengah hari dan Ekron akan dibongkar-bangkirkan.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 5, 'Celakalah kamu penduduk Daerah Tepi Laut, kamu bangsa Kreti! Terhadap kamulah firman TUHAN ini: Hai Kanaan, tanah orang Filistin! Aku akan membinasakan engkau, sehingga tidak ada lagi pendudukmu.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 6, 'Daerah Tepi Laut akan menjadi tempat kediaman bagi gembala-gembala dan kandang berpagar bagi kambing domba.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 7, 'Daerah Pinggir Laut akan menjadi kepunyaan sisa-sisa kaum Yehuda. Mereka akan merumput di sana dan berbaring di rumah-rumah Askelon pada malam hari; sebab TUHAN, Allah mereka, akan memperhatikan mereka dan akan memulihkan keadaan mereka.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 8, '"Aku telah mendengar pencelaan dari pihak Moab dan kata-kata nista dari pihak bani Amon, bagaimana mereka mencela umat-Ku dan membesarkan dirinya terhadap daerah umat-Ku itu.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 9, 'Sebab itu, demi Aku yang hidup?demikianlah firman TUHAN semesta alam, Allah Israel?maka Moab akan menjadi seperti Sodom dan bani Amon seperti Gomora, yakni menjadi padang jeruju dan tempat penggalian garam dan tempat sunyi sepi sampai selama-lamanya. Sisa-sisa umat-Ku akan menjarah mereka dan yang masih tinggal dari bangsa-Ku itu akan memiliki mereka sebagai warisan."', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 10, 'Inilah yang menjadi bagian mereka sebagai ganti kecongkakan mereka, sebab mereka telah mencela dan membesarkan diri terhadap umat TUHAN semesta alam.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 11, 'TUHAN akan mendahsyatkan mereka, sebab Ia akan melenyapkan para allah di bumi, dan kepada-Nya akan sujud menyembah setiap bangsa daerah pesisir, masing-masing dari tempatnya.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 12, 'Kamupun, hai orang Etiopia, akan mati tertikam oleh pedang-Ku.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 13, 'Ia akan mengacungkan tangan-Nya terhadap Utara, akan membinasakan Asyur, dan akan membuat Niniwe menjadi tempat yang sunyi sepi, kering seperti padang gurun.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 14, 'Dan di tengah-tengahnya akan berbaring kawanan binatang, yakni segala macam binatang hutan; baik burung undan maupun burung bangau akan bermalam di hulu tiangnya; burung ponggok akan berbunyi di tingkap, burung gagak di ambang pintu: Pemapan dari kayu aras telah tersingkap!', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 2, 15, 'Itulah kota yang beria-ria yang penduduknya begitu tenteram dan yang berkata dalam hatinya: "Hanya ada aku dan tidak ada yang lain!" Betapa dia sudah menjadi tempat yang tandus, tempat pembaringan bagi binatang-binatang liar. Setiap orang yang lewat dari padanya akan bersuit dan mengayun-ayunkan tangannya.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 1, 'Celakalah si pemberontak dan si cemar, hai kota yang penuh penindasan!', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 2, 'Ia tidak mau mendengarkan teguran siapapun dan tidak mempedulikan kecaman; kepada TUHAN ia tidak percaya dan kepada Allahnya ia tidak menghadap.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 3, 'Para pemukanya di tengah-tengahnya adalah singa yang mengaum; para hakimnya adalah serigala pada waktu malam yang tidak meninggalkan apapun sampai pagi hari.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 4, 'Para nabinya adalah orang-orang ceroboh dan pengkhianat; para imamnya menajiskan apa yang kudus, memperkosa hukum Taurat.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 5, 'Tetapi TUHAN adil di tengah-tengahnya, tidak berbuat kelaliman. Pagi demi pagi Ia memberi hukum-Nya; itu tidak pernah ketinggalan pada waktu fajar. Tetapi orang lalim tidak kenal malu!', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 6, '"Aku telah melenyapkan bangsa-bangsa; menara-menara penjuru mereka telah musnah. Aku telah merusakkan jalan-jalannya, sehingga tidak ada orang yang lewat. Kota-kota mereka telah ditanduskan, sehingga tidak ada orang dan tidak ada penduduk.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 7, 'Aku sangka: Tentulah ia sekarang akan takut kepada-Ku, akan mempedulikan kecaman dan segala yang Kutugaskan kepadanya tidak akan lenyap dari penglihatannya. Tetapi sesungguhnya mereka makin giat menjadikan busuk perbuatan mereka.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 8, 'Oleh karena itu tunggulah Aku?demikianlah firman TUHAN?pada hari Aku bangkit sebagai saksi. Sebab keputusan-Ku ialah mengumpulkan bangsa-bangsa dan menghimpunkan kerajaan-kerajaan untuk menumpahkan ke atas mereka geram-Ku, yakni segenap murka-Ku yang bernyala-nyala, sebab seluruh bumi akan dimakan habis oleh api cemburu-Ku."', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 9, '"Tetapi sesudah itu Aku akan memberikan bibir lain kepada bangsa-bangsa, yakni bibir yang bersih, supaya sekaliannya mereka memanggil nama TUHAN, beribadah kepada-Nya dengan bahu-membahu.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 10, 'Dari seberang sungai-sungai negeri Etiopia orang-orang yang memuja Aku, yang terserak-serak, akan membawa persembahan kepada-Ku.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 11, 'Pada hari itu engkau tidak akan mendapat malu karena segala perbuatan durhaka yang kaulakukan terhadap Aku, sebab pada waktu itu Aku akan menyingkirkan dari padamu orang-orangmu yang ria congkak, dan engkau tidak akan lagi meninggikan dirimu di gunung-Ku yang kudus.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 12, 'Di antaramu akan Kubiarkan hidup suatu umat yang rendah hati dan lemah, dan mereka akan mencari perlindungan pada nama TUHAN,', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 13, 'yakni sisa Israel itu. Mereka tidak akan melakukan kelaliman atau berbicara bohong; dalam mulut mereka tidak akan terdapat lidah penipu; ya, mereka akan seperti domba yang makan rumput dan berbaring dengan tidak ada yang mengganggunya."', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 14, 'Bersorak-sorailah, hai puteri Sion, bertempik-soraklah, hai Israel! Bersukacitalah dan beria-rialah dengan segenap hati, hai puteri Yerusalem!', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 15, 'TUHAN telah menyingkirkan hukuman yang jatuh atasmu, telah menebas binasa musuhmu. Raja Israel, yakni TUHAN, ada di antaramu; engkau tidak akan takut kepada malapetaka lagi.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 16, 'Pada hari itu akan dikatakan kepada Yerusalem: "Janganlah takut, hai Sion! Janganlah tanganmu menjadi lemah lesu.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 17, 'TUHAN Allahmu ada di antaramu sebagai pahlawan yang memberi kemenangan. Ia bergirang karena engkau dengan sukacita, Ia membaharui engkau dalam kasih-Nya, Ia bersorak-sorak karena engkau dengan sorak-sorai,', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 18, 'seperti pada hari pertemuan raya." "Aku akan mengangkat malapetaka dari padamu, sehingga oleh karenanya engkau tidak lagi menanggung cela.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 19, 'Sesungguhnya pada waktu itu Aku akan bertindak terhadap segala penindasmu, tetapi Aku akan menyelamatkan yang pincang, mengumpulkan yang terpencar dan akan membuat mereka yang mendapat malu menjadi kepujian dan kenamaan di seluruh bumi.', 'id', 'TB'),
  ('36', 'zef', 'Zefanya', 3, 20, 'Pada waktu itu Aku akan membawa kamu pulang, yakni pada waktu Aku mengumpulkan kamu, sebab Aku mau membuat kamu menjadi kenamaan dan kepujian di antara segala bangsa di bumi dengan memulihkan keadaanmu di depan mata mereka," firman TUHAN.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 1, 'Pada tahun yang kedua zaman raja Darius, dalam bulan yang keenam, pada hari pertama bulan itu, datanglah firman TUHAN dengan perantaraan nabi Hagai kepada Zerubabel bin Sealtiel, bupati Yehuda, dan kepada Yosua bin Yozadak, imam besar, bunyinya:', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 2, '"Beginilah firman TUHAN semesta alam: Bangsa ini berkata: Sekarang belum tiba waktunya untuk membangun kembali rumah TUHAN!"', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 3, 'Maka datanglah firman TUHAN dengan perantaraan nabi Hagai, bunyinya:', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 4, '"Apakah sudah tiba waktunya bagi kamu untuk mendiami rumah-rumahmu yang dipapani dengan baik, sedang Rumah ini tetap menjadi reruntuhan?', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 5, 'Oleh sebab itu, beginilah firman TUHAN semesta alam: Perhatikanlah keadaanmu!', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 6, 'Kamu menabur banyak, tetapi membawa pulang hasil sedikit; kamu makan, tetapi tidak sampai kenyang; kamu minum, tetapi tidak sampai puas; kamu berpakaian, tetapi badanmu tidak sampai panas; dan orang yang bekerja untuk upah, ia bekerja untuk upah yang ditaruh dalam pundi-pundi yang berlobang!', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 7, 'Beginilah firman TUHAN semesta alam: Perhatikanlah keadaanmu!', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 8, 'Jadi naiklah ke gunung, bawalah kayu dan bangunlah Rumah itu; maka Aku akan berkenan kepadanya dan akan menyatakan kemuliaan-Ku di situ, firman TUHAN.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 9, 'Kamu mengharapkan banyak, tetapi hasilnya sedikit, dan ketika kamu membawanya ke rumah, Aku menghembuskannya. Oleh karena apa? demikianlah firman TUHAN semesta alam. Oleh karena rumah-Ku yang tetap menjadi reruntuhan, sedang kamu masing-masing sibuk dengan urusan rumahnya sendiri.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 10, 'Itulah sebabnya langit menahan embunnya dan bumi menahan hasilnya,', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 11, 'dan Aku memanggil kekeringan datang ke atas negeri, ke atas gunung-gunung, ke atas gandum, ke atas anggur, ke atas minyak, ke atas segala yang dihasilkan tanah, ke atas manusia dan hewan dan ke atas segala hasil usaha."', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 12, 'Lalu Zerubabel bin Sealtiel dan Yosua bin Yozadak, imam besar, dan selebihnya dari bangsa itu mendengarkan suara TUHAN, Allah mereka, dan juga perkataan nabi Hagai, sesuai dengan apa yang disuruhkan kepadanya oleh TUHAN, Allah mereka; lalu takutlah bangsa itu kepada TUHAN.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 13, 'Maka berkatalah Hagai, utusan TUHAN itu, menurut pesan TUHAN kepada bangsa itu, demikian: "Aku ini menyertai kamu, demikianlah firman TUHAN."', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 14, 'TUHAN menggerakkan semangat Zerubabel bin Sealtiel, bupati Yehuda, dan semangat Yosua bin Yozadak, imam besar, dan semangat selebihnya dari bangsa itu, maka datanglah mereka, lalu melakukan pekerjaan pembangunan rumah TUHAN semesta alam, Allah mereka,', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 1, 15, '(2-1a) pada hari yang kedua puluh empat dalam bulan yang keenam. (2-1b) Pada tahun yang kedua zaman raja Darius,', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 1, '(2-2) dalam bulan yang ketujuh, pada tanggal dua puluh satu bulan itu, datanglah firman TUHAN dengan perantaraan nabi Hagai, bunyinya:', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 2, '(2-3) "Katakanlah kepada Zerubabel bin Sealtiel, bupati Yehuda, dan kepada Yosua bin Yozadak, imam besar, dan kepada selebihnya dari bangsa itu, demikian:', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 3, '(2-4) Masih adakah di antara kamu yang telah melihat Rumah ini dalam kemegahannya semula? Dan bagaimanakah kamu lihat keadaannya sekarang? Bukankah keadaannya di matamu seperti tidak ada artinya?', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 4, '(2-5) Tetapi sekarang, kuatkanlah hatimu, hai Zerubabel, demikianlah firman TUHAN; kuatkanlah hatimu, hai Yosua bin Yozadak, imam besar; kuatkanlah hatimu, hai segala rakyat negeri, demikianlah firman TUHAN; bekerjalah, sebab Aku ini menyertai kamu, demikianlah firman TUHAN semesta alam,', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 5, '(2-6) sesuai dengan janji yang telah Kuikat dengan kamu pada waktu kamu keluar dari Mesir. Dan Roh-Ku tetap tinggal di tengah-tengahmu. Janganlah takut!', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 6, '(2-7) Sebab beginilah firman TUHAN semesta alam: Sedikit waktu lagi maka Aku akan menggoncangkan langit dan bumi, laut dan darat;', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 7, '(2-8) Aku akan menggoncangkan segala bangsa, sehingga barang yang indah-indah kepunyaan segala bangsa datang mengalir, maka Aku akan memenuhi Rumah ini dengan kemegahan, firman TUHAN semesta alam.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 8, '(2-9) Kepunyaan-Kulah perak dan kepunyaan-Kulah emas, demikianlah firman TUHAN semesta alam.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 9, '(2-10) Adapun Rumah ini, kemegahannya yang kemudian akan melebihi kemegahannya yang semula, firman TUHAN semesta alam, dan di tempat ini Aku akan memberi damai sejahtera, demikianlah firman TUHAN semesta alam."', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 10, '(2-11) Pada tanggal dua puluh empat bulan yang kesembilan, pada tahun yang kedua zaman Darius, datanglah firman TUHAN kepada nabi Hagai, bunyinya:', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 11, '(2-12) "Beginilah firman TUHAN semesta alam itu: Tanyakanlah pengajaran kepada para imam.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 12, '(2-13) Andaikata seseorang membawa daging kudus dalam punca bajunya, lalu dengan puncanya itu ia menyentuh roti atau sesuatu masakan atau anggur atau minyak atau sesuatu yang dapat dimakan, menjadi kuduskah yang disentuh itu?" Lalu para imam itu menjawab, katanya: "Tidak!"', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 13, '(2-14) Berkatalah pula Hagai: "Jika seseorang yang najis oleh mayat menyentuh semuanya ini, menjadi najiskah yang disentuh itu?" Lalu para imam itu menjawab, katanya: "Tentu!"', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 14, '(2-15) Maka berbicaralah Hagai, katanya: "Begitu juga dengan umat ini dan dengan bangsa ini di hadapan-Ku, demikianlah firman TUHAN, dan dengan segala yang dibuat tangan mereka; dan yang dipersembahkan mereka di sana adalah najis."', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 15, '(2-16) "Maka sekarang, perhatikanlah mulai dari hari ini dan selanjutnya! Sebelum ditaruh orang batu demi batu untuk pembangunan bait TUHAN,', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 16, '(2-17) bagaimana keadaanmu? Ketika orang pergi melihat suatu timbunan gandum yang seharusnya sebanyak dua puluh gantang, hanya ada sepuluh; dan ketika orang pergi ke tempat pemerasan anggur untuk mencedok lima puluh takar, hanya ada dua puluh.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 17, '(2-18) Aku telah memukul kamu dengan hama dan penyakit gandum dan segala yang dibuat tanganmu dengan hujan batu; namun kamu tidak berbalik kepada-Ku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 18, '(2-19) Perhatikanlah mulai dari hari ini dan selanjutnya?mulai dari hari yang kedua puluh empat bulan kesembilan. Mulai dari hari diletakkannya dasar bait TUHAN perhatikanlah', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 19, '(2-20) apakah benih masih tinggal tersimpan dalam lumbung, dan apakah pohon anggur dan pohon ara, pohon delima dan pohon zaitun belum berbuah? Mulai dari hari ini Aku akan memberi berkat!"', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 20, '(2-21) Maka datanglah firman TUHAN untuk kedua kalinya kepada Hagai pada tanggal dua puluh empat bulan itu, bunyinya:', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 21, '(2-22) "Katakanlah kepada Zerubabel, bupati Yehuda, begini: Aku akan menggoncangkan langit dan bumi', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 22, '(2-23) dan akan menunggangbalikkan takhta raja-raja; Aku akan memunahkan kekuasaan kerajaan bangsa-bangsa dan akan menjungkirbalikkan kereta dan pengendaranya; kuda dan pengendaranya akan mati rebah, masing-masing oleh pedang temannya.', 'id', 'TB'),
  ('37', 'hag', 'Hagai', 2, 23, '(2-24) Pada waktu itu, demikianlah firman TUHAN semesta alam, Aku akan mengambil engkau, hai Zerubabel bin Sealtiel, hamba-Ku?demikianlah firman TUHAN?dan akan menjadikan engkau seperti cincin meterai; sebab engkaulah yang Kupilih, demikianlah firman TUHAN semesta alam."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 1, 'Dalam bulan yang kedelapan pada tahun kedua zaman Darius datanglah firman TUHAN kepada nabi Zakharia bin Berekhya bin Ido, bunyinya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 2, '"Sangat murka TUHAN atas nenek moyangmu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 3, 'Sebab itu katakanlah kepada mereka: Beginilah firman TUHAN semesta alam: Kembalilah kepada-Ku, demikianlah firman TUHAN semesta alam, maka Akupun akan kembali kepadamu, firman TUHAN semesta alam.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 4, 'Janganlah kamu seperti nenek moyangmu yang kepadanya para nabi yang dahulu telah menyerukan, demikian: Beginilah firman TUHAN semesta alam: Berbaliklah dari tingkah lakumu yang buruk dan dari perbuatanmu yang jahat! Tetapi mereka tidak mau mendengarkan dan tidak mau menghiraukan Aku, demikianlah firman TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 5, 'Nenek moyangmu, di mana mereka? Dan para nabi, apakah mereka hidup untuk selama-lamanya?', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 6, 'Tetapi segala firman dan ketetapan-Ku yang telah Kuperintahkan kepada hamba-hamba-Ku, para nabi, bukankah itu telah sampai kepada nenek moyangmu? Maka bertobatlah mereka serta berkata: Sebagaimana TUHAN semesta alam bermaksud mengambil tindakan terhadap kita sesuai dengan tingkah laku kita dan perbuatan kita, demikianlah Ia mengambil tindakan terhadap kita!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 7, 'Pada hari yang kedua puluh empat dari bulan yang kesebelas?itulah bulan Syebat?pada tahun yang kedua zaman Darius datanglah firman TUHAN kepada nabi Zakharia bin Berekhya bin Ido, bunyinya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 8, '"Tadi malam aku mendapat suatu penglihatan: tampak seorang yang menunggang kuda merah! Dia sedang berdiri di antara pohon-pohon murad yang di dalam jurang; dan di belakangnya ada kuda-kuda yang merah, yang merah jambu dan yang putih.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 9, 'Maka aku bertanya: Apakah arti semuanya ini, ya tuanku? Lalu malaikat yang berbicara dengan aku itu menjawab: Aku ini akan memperlihatkan kepadamu apa arti semuanya ini!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 10, 'Orang yang berdiri di antara pohon-pohon murad itu mulai berbicara, katanya: Inilah mereka semua yang diutus TUHAN untuk menjelajahi bumi!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 11, 'Berbicaralah mereka kepada Malaikat TUHAN yang berdiri di antara pohon-pohon murad itu, katanya: Kami telah menjelajahi bumi, dan sesungguhnya seluruh bumi itu tenang dan aman.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 12, 'Berbicaralah Malaikat TUHAN itu, katanya: Ya TUHAN semesta alam, berapa lama lagi Engkau tidak menyayangi Yerusalem dan kota-kota Yehuda yang telah tujuh puluh tahun lamanya Kaumurkai itu?', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 13, 'Lalu kepada malaikat, yang berbicara dengan aku itu, TUHAN menjawab dengan kata-kata yang ramah dan yang menghiburkan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 14, 'Berkatalah kepadaku malaikat yang berbicara dengan aku itu: Serukanlah ini: Beginilah firman TUHAN semesta alam: Sangat besar usaha-Ku untuk Yerusalem dan Sion,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 15, 'tetapi sangat besar murka-Ku terhadap bangsa-bangsa yang merasa dirinya aman, yang, sementara Aku murka sedikit, telah membantu menimbulkan kejahatan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 16, 'Sebab itu, beginilah firman TUHAN, Aku kembali lagi kepada Yerusalem dengan kasih sayang. Rumah-Ku akan didirikan pula di sana, demikianlah firman TUHAN semesta alam, dan tali pengukur akan direntangkan lagi di atas Yerusalem.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 17, 'Serukanlah ini selanjutnya: Beginilah firman TUHAN semesta alam: Kota-kota-Ku akan berlimpah-limpah pula dengan kebajikan, dan TUHAN akan menghiburkan Sion dan akan memilih Yerusalem pula."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 18, 'Aku melayangkan mataku dan melihat: tampak empat tanduk.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 19, 'Lalu aku bertanya kepada malaikat yang berbicara dengan aku itu: "Apakah arti semuanya ini?" Maka ia menjawab aku: "Inilah tanduk-tanduk yang telah menyerakkan Yehuda, Israel dan Yerusalem."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 20, 'Kemudian TUHAN memperlihatkan kepadaku empat tukang besi.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 1, 21, 'Lalu aku bertanya: "Orang-orang ini datang untuk melakukan apa?" Maka ia menjawab: "Inipun adalah tanduk-tanduk yang telah menyerakkan Yehuda, sehingga tidak seorangpun berani mengangkat kepalanya. Dan semuanya ini datang untuk mengejutkan mereka, yakni untuk menghempaskan tanduk bangsa-bangsa yang telah mengangkat tanduk terhadap tanah Yehuda hendak menyerakkannya."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 1, 'Aku melayangkan mataku dan melihat: tampak seorang yang memegang tali pengukur.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 2, 'Lalu aku bertanya: "Ke manakah engkau ini pergi?" Maka ia menjawab aku: "Ke Yerusalem, untuk mengukurnya, untuk melihat berapa lebarnya dan panjangnya."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 3, 'Dan sementara malaikat yang berbicara dengan aku itu maju ke depan, majulah seorang malaikat lain mendekatinya,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 4, 'yang diberi perintah: "Berlarilah, katakanlah kepada orang muda yang di sana itu, demikian: Yerusalem akan tetap tinggal seperti padang terbuka oleh karena banyaknya manusia dan hewan di dalamnya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 5, 'Dan Aku sendiri, demikianlah firman TUHAN, akan menjadi tembok berapi baginya di sekelilingnya, dan Aku akan menjadi kemuliaan di dalamnya."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 6, 'Ayo, ayo, larilah dari Tanah Utara, demikianlah firman TUHAN; sebab ke arah keempat mata angin Aku telah menyerakkan kamu, demikianlah firman TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 7, 'Ayo, luputkanlah dirimu ke Sion, hai, penduduk Babel!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 8, 'Sebab beginilah firman TUHAN semesta alam, yang dalam kemuliaan-Nya telah mengutus aku, mengenai bangsa-bangsa yang telah menjarah kamu?sebab siapa yang menjamah kamu, berarti menjamah biji mata-Nya?:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 9, '"Sesungguhnya Aku akan menggerakkan tangan-Ku terhadap mereka, dan mereka akan menjadi jarahan bagi orang-orang yang tadinya takluk kepada mereka. Maka kamu akan mengetahui bahwa TUHAN semesta alam yang mengutus aku.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 10, 'Bersorak-sorailah dan bersukarialah, hai puteri Sion, sebab sesungguhnya Aku datang dan diam di tengah-tengahmu, demikianlah firman TUHAN;', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 11, 'dan banyak bangsa akan menggabungkan diri kepada TUHAN pada waktu itu dan akan menjadi umat-Ku dan Aku akan diam di tengah-tengahmu." Maka engkau akan mengetahui, bahwa TUHAN semesta alam yang mengutus aku kepadamu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 12, 'Dan TUHAN akan mengambil Yehuda sebagai milik-Nya di tanah yang kudus, dan Ia akan memilih Yerusalem pula.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 2, 13, 'Berdiam dirilah, hai segala makhluk, di hadapan TUHAN, sebab Ia telah bangkit dari tempat kediaman-Nya yang kudus.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 1, 'Kemudian ia memperlihatkan kepadaku imam besar Yosua berdiri di hadapan Malaikat TUHAN sedang Iblis berdiri di sebelah kanannya untuk mendakwa dia.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 2, 'Lalu berkatalah Malaikat TUHAN kepada Iblis itu: "TUHAN kiranya menghardik engkau, hai Iblis! TUHAN, yang memilih Yerusalem, kiranya menghardik engkau! Bukankah dia ini puntung yang telah ditarik dari api?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 3, 'Adapun Yosua mengenakan pakaian yang kotor, waktu dia berdiri di hadapan Malaikat itu,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 4, 'yang memberikan perintah kepada orang-orang yang melayaninya: "Tanggalkanlah pakaian yang kotor itu dari padanya." Dan kepada Yosua ia berkata: "Lihat, dengan ini aku telah menjauhkan kesalahanmu dari padamu! Aku akan mengenakan kepadamu pakaian pesta."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 5, 'Kemudian ia berkata: "Taruhlah serban tahir pada kepalanya!" Maka mereka menaruh serban tahir pada kepalanya dan mengenakan pakaian kepadanya, sedang Malaikat TUHAN berdiri di situ.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 6, 'Lalu Malaikat TUHAN itu memberi jaminan kepada Yosua, katanya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 7, '"Beginilah firman TUHAN semesta alam: Apabila engkau hidup menurut jalan yang Kutunjukkan dan melakukan tugas yang Kuberikan kepadamu, maka engkau akan memerintah rumah-Ku dan mengurus pelataran-Ku, dan Aku akan mengizinkan engkau masuk ke antara mereka yang berdiri melayani di sini.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 8, 'Dengarkanlah, hai imam besar Yosua! Engkau dan teman-temanmu yang duduk di hadapanmu?sungguh kamu merupakan suatu lambang. Sebab, sesungguhnya Aku akan mendatangkan hamba-Ku, yakni Sang Tunas.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 9, 'Sebab sesungguhnya permata yang telah Kuserahkan kepada Yosua?satu permata yang bermata tujuh?sesungguhnya Aku akan mengukirkan ukiran di atasnya, demikianlah firman TUHAN semesta alam, dan Aku akan menghapuskan kesalahan negeri ini dalam satu hari saja.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 3, 10, 'Pada hari itu, demikianlah firman TUHAN semesta alam, setiap orang dari padamu akan mengundang temannya duduk di bawah pohon anggur dan di bawah pohon ara."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 1, 'Datanglah kembali malaikat yang berbicara dengan aku itu, lalu dibangunkannyalah aku seperti seorang yang dibangunkan dari tidurnya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 2, 'Maka berkatalah ia kepadaku: "Apa yang engkau lihat?" Jawabku: "Aku melihat: tampak sebuah kandil, dari emas seluruhnya, dan tempat minyaknya di bagian atasnya; kandil itu ada tujuh pelitanya dan ada tujuh corot pada masing-masing pelita yang ada di bagian atasnya itu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 3, 'Dan pohon zaitun ada terukir padanya, satu di sebelah kanan tempat minyak itu dan satu di sebelah kirinya."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 4, 'Lalu berbicaralah aku, kataku kepada malaikat yang berbicara dengan aku itu: "Apakah arti semuanya ini, tuanku?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 5, 'Maka berbicaralah malaikat yang berbicara dengan aku itu, katanya kepadaku: "Tidakkah engkau tahu, apa arti semuanya ini?" Jawabku: "Tidak, tuanku!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 6, 'Maka berbicaralah ia, katanya: "Inilah firman TUHAN kepada Zerubabel bunyinya: Bukan dengan keperkasaan dan bukan dengan kekuatan, melainkan dengan roh-Ku, firman TUHAN semesta alam.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 7, 'Siapakah engkau, gunung yang besar? Di depan Zerubabel engkau menjadi tanah rata. Ia akan mengangkat batu utama, sedang orang bersorak: Bagus! Bagus sekali batu itu!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 8, 'Kemudian datanglah firman TUHAN kepadaku, demikian:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 9, '"Tangan Zerubabel telah meletakkan dasar Rumah ini, dan tangannya juga akan menyelesaikannya. Maka kamu akan mengetahui, bahwa TUHAN semesta alam yang mengutus aku kepadamu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 10, 'Sebab siapa yang memandang hina hari peristiwa-peristiwa yang kecil, mereka akan bersukaria melihat batu pilihan di tangan Zerubabel. Yang tujuh ini adalah mata TUHAN, yang menjelajah seluruh bumi."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 11, 'Lalu berbicaralah aku kepadanya: "Apakah arti kedua pohon zaitun yang di sebelah kanan dan di sebelah kiri kandil ini?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 12, 'Untuk kedua kalinya berbicaralah aku kepadanya: "Apakah arti kedua dahan pohon zaitun yang di samping kedua pipa emas yang menyalurkan cairan emas dari atasnya itu?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 13, 'Ia menjawab aku: "Tidakkah engkau tahu, apa arti semuanya ini?" Jawabku: "Tidak, tuanku!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 4, 14, 'Lalu ia berkata: "Inilah kedua orang yang diurapi yang berdiri di dekat Tuhan seluruh bumi!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 1, 'Aku melayangkan mataku pula, maka aku melihat: tampak sebuah gulungan kitab yang terbang.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 2, 'Berkatalah ia kepadaku: "Apa yang engkau lihat?" Jawabku: "Aku melihat sebuah gulungan kitab yang terbang; panjangnya dua puluh hasta dan lebarnya sepuluh hasta."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 3, 'Lalu ia berkata kepadaku: "Inilah sumpah serapah yang keluar menimpa seluruh negeri; sebab menurut sumpah serapah itu setiap pencuri di sini masih bebas dari hukuman, dan setiap orang yang bersumpah palsu di sini juga masih bebas dari hukuman.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 4, 'Aku telah menyuruhnya keluar, demikianlah firman TUHAN semesta alam, supaya itu masuk ke dalam rumah pencuri dan ke dalam rumah orang yang bersumpah palsu demi nama-Ku, dan supaya itu bermalam di dalam rumah mereka dan memusnahkannya, baik kayunya maupun batu-batunya."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 5, 'Tampillah malaikat yang berbicara dengan aku itu, katanya kepadaku: "Cobalah layangkan matamu dan lihatlah apa yang muncul itu!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 6, 'Lalu tanyaku: "Apa itu?" Jawabnya: "Yang muncul itu sebuah gantang!" Lagi katanya: "Inilah kejahatan mereka di seluruh negeri!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 7, 'Lihat, tutup timah gantang itu telah terangkat, dan seorang perempuan duduk di dalamnya!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 8, 'Kemudian berkatalah ia: "Itulah kefasikan!" Lalu didorongnyalah perempuan itu kembali ke dalam gantang dan dibantingnyalah batu timah itu ke mulut gantang.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 9, 'Lalu aku melayangkan mataku dan aku melihat: tampak tampil dua orang perempuan yang sayapnya didorong oleh angin. Adapun sayap mereka adalah sayap seperti burung ranggung. Mereka mengangkut gantang itu di antara bumi dan langit.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 10, 'Bertanyalah aku kepada malaikat yang berbicara dengan aku itu: "Ke mana mereka membawa gantang itu?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 5, 11, 'Jawabnya kepadaku: "Ke tanah Sinear, untuk mendirikan sebuah rumah bagi perempuan itu. Dan apabila itu selesai, maka mereka akan menempatkan dia di sana di tempat rumah itu didirikan."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 1, 'Aku melayangkan mataku pula, maka aku melihat: tampak keluar empat kereta dari antara dua gunung. Adapun gunung-gunung itu adalah gunung-gunung tembaga.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 2, 'Kereta pertama ditarik oleh kuda merah, kereta kedua oleh kuda hitam.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 3, 'Kereta ketiga oleh kuda putih, dan kereta keempat oleh kuda yang berbelang-belang dan berloreng-loreng.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 4, 'Berbicaralah aku kepada malaikat yang berbicara dengan aku itu: "Apakah arti semuanya ini, tuanku?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 5, 'Berbicaralah malaikat itu kepadaku: "Semuanya ini keluar ke arah keempat mata angin, sesudah mereka menghadap kepada Tuhan seluruh bumi."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 6, 'Yang ditarik oleh kuda hitam itu keluar ke Tanah Utara; yang putih itu keluar ke arah barat; yang berbelang-belang itu keluar ke Tanah Selatan;', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 7, 'dan yang merah itu keluar, gelisah untuk pergi, hendak menjelajahi bumi. Lalu berkatalah ia: "Pergilah, jelajahilah bumi!" Maka mereka menjelajahi bumi.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 8, 'Kemudian berteriaklah ia kepadaku: "Lihat, mereka yang keluar ke Tanah Utara itu akan menenteramkan roh-Ku di Tanah Utara."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 9, 'Datanglah firman TUHAN kepadaku, bunyinya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 10, '"Pergilah pada hari ini juga ke rumah Yosia bin Zefanya dan pungutlah persembahan dari pihak orang-orang buangan, yaitu dari Heldai, Tobia dan Yedaya, semuanya orang-orang yang sudah datang kembali dari Babel,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 11, 'pungutlah perak dan emas, buatlah mahkota dan kenakanlah itu pada kepala imam besar Yosua bin Yozadak;', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 12, 'katakanlah kepadanya: Beginilah firman TUHAN semesta alam: Inilah orang yang bernama Tunas. Ia akan bertunas dari tempatnya dan ia akan mendirikan bait TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 13, 'Dialah yang akan mendirikan bait TUHAN, dan dialah yang akan mendapat keagungan dan akan duduk memerintah di atas takhtanya. Di sebelah kanannya akan ada seorang imam dan permufakatan tentang damai akan ada di antara mereka berdua.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 14, 'Dan mahkota itu akan tetap tinggal dalam bait TUHAN sebagai tanda peringatan akan Heldai, Tobia, Yedaya dan akan Yosia bin Zefanya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 6, 15, 'Orang-orang dari jauh akan datang untuk turut membangun bait TUHAN; maka kamu akan mengetahui bahwa TUHAN semesta alam yang mengutus aku kepadamu. Dan hal ini akan terjadi, apabila kamu dengan baik-baik mendengarkan suara TUHAN Allahmu."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 1, 'Pada tahun yang keempat zaman raja Darius datanglah firman TUHAN kepada Zakharia, pada tanggal empat bulan kesembilan, yakni bulan Kislew.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 2, 'Adapun penduduk Betel telah mengutus Sarezer dan Regem-Melekh serta orang-orangnya untuk melunakkan hati TUHAN,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 3, 'untuk menanyakan kepada para imam dari rumah TUHAN semesta alam dan kepada nabi, demikian: "Haruskah kami sekalian menangis dan berpantang dalam bulan yang kelima seperti yang telah kami lakukan bertahun-tahun lamanya?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 4, 'Maka datanglah firman TUHAN semesta alam kepadaku, bunyinya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 5, '"Katakanlah kepada seluruh rakyat negeri dan kepada para imam, demikian: Ketika kamu berpuasa dan meratap dalam bulan yang kelima dan yang ketujuh selama tujuh puluh tahun ini, adakah kamu sungguh-sungguh berpuasa untuk Aku?', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 6, 'Dan ketika kamu makan dan ketika kamu minum, bukankah kamu makan dan minum untuk dirimu sendiri?', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 7, 'Bukankah ini firman yang telah disampaikan TUHAN dengan perantaraan para nabi yang dahulu, ketika Yerusalem dengan kota-kota yang di sekelilingnya masih didiami orang dan masih sentosa dan Tanah Negeb dan Daerah Bukit masih didiami?"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 8, 'Firman TUHAN datang kepada Zakharia, bunyinya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 9, '"Beginilah firman TUHAN semesta alam: Laksanakanlah hukum yang benar dan tunjukkanlah kesetiaan dan kasih sayang kepada masing-masing!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 10, 'Janganlah menindas janda dan anak yatim, orang asing dan orang miskin, dan janganlah merancang kejahatan dalam hatimu terhadap masing-masing."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 11, 'Tetapi mereka tidak mau menghiraukan, dilintangkannya bahunya untuk melawan dan ditulikannya telinganya supaya jangan mendengar.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 12, 'Mereka membuat hati mereka keras seperti batu amril, supaya jangan mendengar pengajaran dan firman yang disampaikan TUHAN semesta alam melalui roh-Nya dengan perantaraan para nabi yang dahulu. Oleh sebab itu datang murka yang hebat dari pada TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 13, '"Seperti mereka tidak mendengarkan pada waktu dipanggil, demikianlah Aku tidak mendengarkan pada waktu mereka memanggil, firman TUHAN semesta alam.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 7, 14, 'Oleh sebab itu Aku meniupkan mereka seperti angin badai ke antara segala bangsa yang tidak dikenal mereka, dan sesudahnya tanah itu menjadi sunyi sepi, sehingga tidak ada yang lalu lalang di sana; demikianlah mereka membuat negeri yang indah itu menjadi tempat yang sunyi sepi."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 1, 'Datanglah firman TUHAN semesta alam, bunyinya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 2, '"Beginilah firman TUHAN semesta alam: Aku berusaha untuk Sion dengan kegiatan yang besar dan dengan kehangatan amarah yang besar.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 3, 'Beginilah firman TUHAN: Aku akan kembali ke Sion dan akan diam di tengah-tengah Yerusalem. Yerusalem akan disebut Kota Setia, dan gunung TUHAN semesta alam akan disebut Gunung Kudus.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 4, 'Beginilah firman TUHAN semesta alam: Akan ada lagi kakek-kakek dan nenek-nenek duduk di jalan-jalan Yerusalem, masing-masing memegang tongkat karena lanjut usianya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 5, 'Dan jalan-jalan kota itu akan penuh dengan anak laki-laki dan anak perempuan yang bermain-main di situ.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 6, 'Beginilah firman TUHAN semesta alam: Kalau pada waktu itu sisa-sisa bangsa ini menganggap hal itu ajaib, apakah Aku akan menganggapnya ajaib? demikianlah firman TUHAN semesta alam.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 7, 'Beginilah firman TUHAN semesta alam: Sesungguhnya, Aku menyelamatkan umat-Ku dari tempat terbitnya matahari sampai kepada tempat terbenamnya,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 8, 'dan Aku akan membawa mereka pulang, supaya mereka diam di tengah-tengah Yerusalem. Maka mereka akan menjadi umat-Ku dan Aku akan menjadi Allah mereka dalam kesetiaan dan kebenaran."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 9, 'Beginilah firman TUHAN semesta alam: "Kuatkanlah hatimu, hai orang-orang yang selama ini telah mendengar firman ini, yang diucapkan para nabi, sejak dasar rumah TUHAN semesta alam diletakkan, untuk mendirikan Bait Suci itu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 10, 'Sebab sebelum waktu itu tidak ada rezeki bagi manusia, juga tidak bagi binatang; dan karena musuh tidak ada keamanan bagi orang yang keluar dan bagi orang yang masuk, lagipula Aku membuat manusia semua bertengkar.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 11, 'Tetapi sekarang, Aku tidak lagi seperti waktu dahulu terhadap sisa-sisa bangsa ini, demikianlah firman TUHAN semesta alam,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 12, 'melainkan Aku akan menabur damai sejahtera. Maka pohon anggur akan memberi buahnya dan tanah akan memberi hasilnya dan langit akan memberi air embunnya. Aku akan memberi semuanya itu kepada sisa-sisa bangsa ini sebagai miliknya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 13, 'Dan kalau dahulu kamu telah menjadi kutuk di antara bangsa-bangsa, hai kaum Yehuda dan kaum Israel, maka sekarang Aku akan menyelamatkan kamu, sehingga kamu menjadi berkat. Janganlah takut, kuatkanlah hatimu!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 14, 'Sebab beginilah firman TUHAN semesta alam: "Kalau dahulu Aku telah bermaksud mendatangkan malapetaka kepada kamu, ketika nenek moyangmu membuat Aku murka, dan Aku tidak menyesal, firman TUHAN semesta alam,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 15, 'maka pada waktu ini Aku kembali bermaksud berbuat baik kepada Yerusalem dan kepada kaum Yehuda. Janganlah takut!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 16, 'Inilah hal-hal yang harus kamu lakukan: Berkatalah benar seorang kepada yang lain dan laksanakanlah hukum yang benar, yang mendatangkan damai di pintu-pintu gerbangmu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 17, 'Janganlah merancang kejahatan dalam hatimu seorang terhadap yang lain dan janganlah mencintai sumpah palsu. Sebab semuanya itu Kubenci, demikianlah firman TUHAN."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 18, 'Datanglah firman TUHAN semesta alam kepadaku, bunyinya:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 19, '"Beginilah firman TUHAN semesta alam: Waktu puasa dalam bulan yang keempat, dalam bulan yang kelima, dalam bulan yang ketujuh dan dalam bulan yang kesepuluh akan menjadi kegirangan dan sukacita dan menjadi waktu-waktu perayaan yang menggembirakan bagi kaum Yehuda. Maka cintailah kebenaran dan damai!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 20, 'Beginilah firman TUHAN semesta alam: "Masih akan datang lagi bangsa-bangsa dan penduduk banyak kota.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 21, 'Dan penduduk kota yang satu akan pergi kepada penduduk kota yang lain, mengatakan: Marilah kita pergi untuk melunakkan hati TUHAN dan mencari TUHAN semesta alam! Kamipun akan pergi!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 22, 'Jadi banyak bangsa dan suku-suku bangsa yang kuat akan datang mencari TUHAN semesta alam di Yerusalem dan melunakkan hati TUHAN."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 8, 23, 'Beginilah firman TUHAN semesta alam: "Pada waktu itu sepuluh orang dari berbagai-bagai bangsa dan bahasa akan memegang kuat-kuat punca jubah seorang Yahudi dengan berkata: Kami mau pergi menyertai kamu, sebab telah kami dengar, bahwa Allah menyertai kamu!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 1, 'Ucapan Ilahi. Firman TUHAN datang atas negeri Hadrakh dan berhenti di Damsyik. Sebab kepunyaan Tuhanlah kota-kota Aram serta segala suku Israel;', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 2, 'juga Hamat yang berbatas kepadanya, pula Tirus dan Sidon, sekalipun mereka sangat bijaksana.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 3, 'Tirus mendirikan tembok benteng bagi dirinya dan menimbun perak seperti debu dan emas seperti lumpur di jalan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 4, 'Namun sesungguhnya, Tuhan akan membuatnya miskin dan akan melontarkan kekuatannya ke dalam laut, dan kota itu sendiri akan habis dimakan api.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 5, 'Askelon akan melihatnya, lalu takut; juga Gaza, lalu gemetar sangat; Ekronpun, sebab harapannya sudah kandas. Dari Gaza raja akan binasa dan Askelon tidak akan didiami lagi.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 6, 'Di Asdod akan diam keturunan campuran, dan kebanggaan orang Filistin akan Kulenyapkan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 7, 'Aku akan melenyapkan darah dari mulutnya dan kejijikan dari antara giginya, dan yang tinggal dari merekapun akan menjadi kepunyaan Allah kita. Mereka akan dianggap seperti suatu kaum di Yehuda, dan orang Ekron seperti orang Yebus.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 8, 'Aku berkemah dekat rumah-Ku sebagai pengawal terhadap mereka yang lalu-lalang; tidak akan ada lagi penindas mendatanginya, sebab sekarang Aku sendiri telah mengindahkannya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 9, 'Bersorak-soraklah dengan nyaring, hai puteri Sion, bersorak-sorailah, hai puteri Yerusalem! Lihat, rajamu datang kepadamu; ia adil dan jaya. Ia lemah lembut dan mengendarai seekor keledai, seekor keledai beban yang muda.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 10, 'Ia akan melenyapkan kereta-kereta dari Efraim dan kuda-kuda dari Yerusalem; busur perang akan dilenyapkan, dan ia akan memberitakan damai kepada bangsa-bangsa. Wilayah kekuasaannya akan terbentang dari laut sampai ke laut dan dari sungai Efrat sampai ke ujung-ujung bumi.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 11, 'Mengenai engkau, oleh karena darah perjanjian-Ku dengan engkau, Aku akan melepaskan orang-orang tahananmu dari lobang yang tidak berair.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 12, 'Kembalilah ke kota bentengmu, hai orang tahanan yang penuh harapan! Pada hari ini juga Aku memberitahukan: Aku akan memberi ganti kepadamu dua kali lipat!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 13, 'Sebab Aku melentur Yehuda bagi-Ku, busur Kuisi dengan Efraim, dan Aku mengayunkan anak-anakmu, hai Sion, terhadap anak-anakmu, hai Yunani, dan Aku akan memakai engkau seperti pedang seorang pahlawan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 14, 'TUHAN akan menampakkan diri kepada mereka, dan anak panah-Nya akan melayang keluar seperti kilat. Dan Tuhan ALLAH akan meniup sangkakala dan akan berjalan maju dalam angin badai dari selatan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 15, 'TUHAN semesta alam akan melindungi mereka, dan mereka akan menghabisi dan menginjak-injak pengumban-pengumban. Mereka akan minum darah seperti minum anggur dan menjadi penuh seperti bokor penyiraman, seperti penjuru-penjuru mezbah.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 16, 'TUHAN, Allah mereka, akan menyelamatkan mereka pada hari itu; seperti kawanan domba umat-Nya itu, sungguh, mereka seperti permata-permata mahkota yang berkilap-kilap, demikianlah mereka di tanah TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 9, 17, 'Sungguh, alangkah baiknya itu dan alangkah indahnya! Teruna bertumbuh pesat karena gandum, dan anak dara karena anggur.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 1, 'Mintalah hujan dari pada TUHAN pada akhir musim semi! Tuhanlah yang membuat awan-awan pembawa hujan deras, dan hujan lebat akan Diberikannya kepada mereka dan tumbuh-tumbuhan di padang kepada setiap orang.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 2, 'Sebab apa yang dikatakan oleh terafim adalah jahat, dan yang dilihat oleh juru-juru tenung adalah dusta, dan mimpi-mimpi yang disebutkan mereka adalah hampa, serta hiburan yang diberikan mereka adalah kesia-siaan. Oleh sebab itu bangsa itu berkeliaran seperti kawanan domba dan menderita sengsara sebab tidak ada gembala.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 3, '"Terhadap para gembala akan bangkit murka-Ku dan terhadap kepala-kepala kawanan kambing Aku akan mengadakan pembalasan, sebab TUHAN semesta alam memperhatikan kawanan ternak-Nya, yakni kaum Yehuda, dan membuat mereka sebagai kuda keagungan-Nya dalam pertempuran.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 4, 'Dari pada mereka akan muncul batu penjuru, dari pada mereka akan muncul patok kemah, dari pada mereka akan muncul busur perang, dari pada mereka akan keluar semua penguasa bersama-sama.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 5, 'Maka mereka akan seperti pahlawan yang menginjak-injak musuh seakan-akan itu lumpur di jalan; mereka akan berperang, sebab TUHAN menyertai mereka, dan mereka akan membuat malu orang-orang yang mengendarai kuda.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 6, 'Aku akan membuat kuat kaum Yehuda, dan Aku menyelamatkan keturunan Yusuf. Aku akan membawa mereka kembali, sebab Aku menyayangi mereka; dan keadaan mereka seakan-akan tidak pernah ditolak oleh Aku, sebab Akulah TUHAN, Allah mereka, dan Aku akan menjawab mereka.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 7, 'Efraim akan seperti seorang pahlawan, hati mereka akan bersukacita seperti oleh anggur. Anak-anak mereka akan melihatnya, lalu bersukacita dan hati mereka bersorak-sorak karena TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 8, 'Aku akan bersiul memanggil mereka dan Aku akan mengumpulkan mereka, sebab Aku sudah membebaskan mereka, dan jumlah mereka menjadi banyak seperti dahulu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 9, 'Sekalipun Aku telah menyerakkan mereka ke antara bangsa-bangsa, tetapi di tempat-tempat yang jauh mereka akan ingat kepada-Ku; mereka akan hidup bersama-sama anak-anak mereka dan mereka akan kembali.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 10, 'Aku akan membawa mereka kembali dari tanah Mesir, dan dari Asyur Aku akan mengumpulkan mereka; Aku akan membawa mereka masuk ke tanah Gilead dan ke Libanon, sehingga tidak ada tempat lagi bagi mereka.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 11, 'Mereka akan menyeberangi laut Mesir dan Ia akan memukul gelombang di laut, sehingga segala tempat yang dalam di sungai Nil menjadi kering. Kebanggaan Asyur akan diturunkan dan tongkat kerajaan Mesir akan lewat.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 10, 12, 'Aku akan menguatkan mereka, dan mereka akan bermegah di dalam nama TUHAN," demikianlah firman TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 1, 'Bukalah pintu-pintumu, hai Libanon, supaya api dapat memakan pohon-pohon arasmu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 2, 'Merataplah, hai pohon sanobar, sebab sudah rebah pohon aras dan sudah dirusakkan pohon-pohon yang hebat! Merataplah, hai pohon-pohon tarbantin Basan, sebab telah rata hutan yang lebat itu!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 3, 'Dengar, para gembala meratap! Sebab kemegahan mereka sudah dirusakkan. Dengar, singa-singa mengaum! Sebab sudah dirusakkan kebanggaan sungai Yordan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 4, 'Beginilah firman TUHAN Allahku kepadaku: "Gembalakanlah domba-domba sembelihan itu!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 5, 'Orang-orang yang membelinya menyembelihnya dengan tidak merasa bersalah dan orang-orang yang menjualnya berkata: Terpujilah TUHAN! Aku telah menjadi kaya! Dan orang-orang yang menggembalakannya tidak mengasihaninya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 6, 'Sebab Aku tidak lagi akan mengasihani penduduk bumi, demikianlah firman TUHAN, melainkan sesungguhnya, Aku akan menyerahkan manusia masing-masing ke dalam tangan gembalanya dan ke dalam tangan rajanya; mereka ini akan menghancurkan bumi dan Aku tidak akan melepaskan seorangpun dari tangan mereka."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 7, 'Maka aku menggembalakan domba-domba sembelihan itu untuk pedagang-pedagang domba. Aku mengambil dua tongkat: yang satu kusebutkan "Kemurahan" dan yang lain kusebutkan "Ikatan"; lalu aku menggembalakan domba-domba itu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 8, 'Dalam satu bulan aku melenyapkan ketiga gembala itu. Kemudian aku tidak dapat menahan hati lagi terhadap domba-domba itu, dan merekapun merasa muak terhadap aku.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 9, 'Lalu aku berkata: "Aku tidak mau lagi menggembalakan kamu; yang hendak mati, biarlah mati; yang hendak lenyap, biarlah lenyap, dan yang masih tinggal itu, biarlah masing-masing memakan daging temannya!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 10, 'Aku mengambil tongkatku "Kemurahan", lalu mematahkannya untuk membatalkan perjanjian yang telah kuikat dengan segala bangsa.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 11, 'Jadi dibatalkanlah perjanjian pada hari itu, maka tahulah pedagang-pedagang domba yang sedang mengamat-amati aku, bahwa itu adalah firman TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 12, 'Lalu aku berkata kepada mereka: "Jika itu kamu anggap baik, berikanlah upahku, dan jika tidak, biarkanlah!" Maka mereka membayar upahku dengan menimbang tiga puluh uang perak.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 13, 'Tetapi berfirmanlah TUHAN kepadaku: "Serahkanlah itu kepada penuang logam!" ?nilai tinggi yang ditaksir mereka bagiku. Lalu aku mengambil ketiga puluh uang perak itu dan menyerahkannya kepada penuang logam di rumah TUHAN.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 14, 'Kemudian aku mematahkan tongkat yang kedua, yaitu "Ikatan", untuk meniadakan persaudaraan antara Yehuda dan Israel.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 15, 'Sesudah itu berfirmanlah TUHAN kepadaku: "Ambillah sekali lagi perkakas seorang gembala yang pandir!', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 16, 'Sebab sesungguhnya, Aku akan membangkitkan di negeri ini seorang gembala yang tidak mengindahkan yang lenyap, yang tidak mencari yang hilang, yang tidak menyembuhkan yang luka, yang tidak memelihara yang sehat, melainkan memakan daging dari yang gemuk dan mencabut kuku mereka.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 11, 17, 'Celakalah gembala-Ku yang pandir, yang meninggalkan domba-domba! Biarlah pedang menimpa lengannya dan menimpa mata kanannya! Biarlah lengannya kering sekering-keringnya, dan mata kanannya menjadi pudar sepudar-pudarnya!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 1, 'Ucapan ilahi. Firman TUHAN tentang Israel: Demikianlah firman TUHAN yang membentangkan langit dan yang meletakkan dasar bumi dan yang menciptakan roh dalam diri manusia:', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 2, '"Sesungguhnya Aku membuat Yerusalem menjadi pasu yang menyebabkan segala bangsa di sekeliling menjadi pening; juga Yehuda akan mengalami kesusahan ketika Yerusalem dikepung.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 3, 'Maka pada waktu itu Aku akan membuat Yerusalem menjadi batu untuk diangkat bagi segala bangsa. Siapa yang mengangkatnya pastilah mendapat luka parah. Segala bangsa di bumi akan berkumpul melawannya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 4, 'Pada waktu itu, demikianlah firman TUHAN, Aku akan membuat segala kuda menjadi bingung, penunggangnya menjadi gila. Atas kaum Yehuda, Aku akan membuka mata-Ku, tetapi segala kuda bangsa akan Kubuat menjadi buta.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 5, 'Sesudah itu kaum-kaum di Yehuda akan berkata dalam hatinya: Penduduk Yerusalem mempunyai kekuatan oleh karena TUHAN semesta alam, Allah mereka.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 6, 'Pada waktu itu Aku akan membuat kaum-kaum di Yehuda seperti anglo berapi di tengah-tengah timbunan kayu dan seperti suluh berapi di tengah-tengah timbunan bulir gandum; api keduanya akan menjilat ke kanan dan ke kiri segala bangsa di sekeliling, tetapi Yerusalem selanjutnya akan tetap tinggal di tempatnya yang dahulu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 7, 'TUHAN akan pertama-tama memberi kemenangan kepada kemah-kemah Yehuda, supaya keluarga Daud dan penduduk Yerusalem jangan terlalu bermegah-megah terhadap Yehuda.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 8, 'Pada waktu itu TUHAN akan melindungi penduduk Yerusalem, dan orang yang tersandung di antara mereka pada waktu itu akan menjadi seperti Daud, dan keluarga Daud akan menjadi seperti Allah, seperti Malaikat TUHAN, yang mengepalai mereka.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 9, 'Maka pada waktu itu Aku berikhtiar untuk memunahkan segala bangsa yang menyerang Yerusalem."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 10, '"Aku akan mencurahkan roh pengasihan dan roh permohonan atas keluarga Daud dan atas penduduk Yerusalem, dan mereka akan memandang kepada dia yang telah mereka tikam, dan akan meratapi dia seperti orang meratapi anak tunggal, dan akan menangisi dia dengan pedih seperti orang menangisi anak sulung.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 11, 'Pada waktu itu ratapan di Yerusalem akan sama besarnya dengan ratapan atas Hadad-Rimon di lembah Megido.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 12, 'Negeri itu akan meratap, setiap kaum keluarga tersendiri; kaum keluarga keturunan Daud tersendiri dan isteri mereka tersendiri; kaum keluarga keturunan Natan tersendiri dan isteri mereka tersendiri;', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 13, 'kaum keluarga keturunan Lewi tersendiri dan isteri mereka tersendiri; kaum keluarga Simei tersendiri dan isteri mereka tersendiri;', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 12, 14, 'juga segala kaum keluarga yang masih tinggal, setiap kaum keluarga tersendiri dan isteri mereka tersendiri."', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 1, '"Pada waktu itu akan terbuka suatu sumber bagi keluarga Daud dan bagi penduduk Yerusalem untuk membasuh dosa dan kecemaran.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 2, 'Maka pada waktu itu, demikianlah firman TUHAN semesta alam, Aku akan melenyapkan nama-nama berhala dari negeri itu, sehingga orang tidak menyebutnya lagi. Juga para nabi dan roh najis akan Kusingkirkan dari negeri itu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 3, 'Dan apabila seseorang masih tampil sebagai nabi, maka ayahnya dan ibunya, yang telah memperanakkan dia, akan berkata kepadanya: Janganlah engkau hidup lagi, sebab yang kaukatakan demi nama TUHAN itu adalah dusta! Lalu ayahnya dan ibunya, yang telah memperanakkan dia, akan menikam dia pada waktu ia bernubuat.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 4, 'Pada waktu itu para nabi masing-masing akan mendapat malu oleh karena penglihatannya sebagai nabi, dan tidak ada lagi dari mereka yang mengenakan jubah berbulu untuk berbohong;', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 5, 'tetapi masing-masing akan berkata: Aku ini bukan seorang nabi, melainkan seorang pengusaha tanah, sebab tanah adalah harta kepunyaanku sejak kecil.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 6, 'Dan apabila ada orang bertanya kepadanya: Bekas luka apakah yang ada pada badanmu ini?, lalu ia akan menjawab: Itulah luka yang kudapat di rumah sahabat-sahabatku!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 7, '"Hai pedang, bangkitlah terhadap gembala-Ku, terhadap orang yang paling karib kepada-Ku!", demikianlah firman TUHAN semesta alam. "Bunuhlah gembala, sehingga domba-domba tercerai-berai! Aku akan mengenakan tangan-Ku terhadap yang lemah.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 8, 'Maka di seluruh negeri, demikianlah firman TUHAN, dua pertiga dari padanya akan dilenyapkan, mati binasa, tetapi sepertiga dari padanya akan tinggal hidup.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 13, 9, 'Aku akan menaruh yang sepertiga itu dalam api dan akan memurnikan mereka seperti orang memurnikan perak. Aku akan menguji mereka, seperti orang menguji emas. Mereka akan memanggil nama-Ku, dan Aku akan menjawab mereka. Aku akan berkata: Mereka adalah umat-Ku, dan mereka akan menjawab: TUHAN adalah Allahku!"', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 1, 'Sesungguhnya, akan datang hari yang ditetapkan TUHAN, maka jarahan yang dirampas dari padamu akan dibagi-bagi di tengah-tengahmu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 2, 'Aku akan mengumpulkan segala bangsa untuk memerangi Yerusalem; kota itu akan direbut, rumah-rumah akan dirampoki dan perempuan-perempuan akan ditiduri. Setengah dari penduduk kota itu harus pergi ke dalam pembuangan, tetapi selebihnya dari bangsa itu tidak akan dilenyapkan dari kota itu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 3, 'Kemudian TUHAN akan maju berperang melawan bangsa-bangsa itu seperti Ia berperang pada hari pertempuran.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 4, 'Pada waktu itu kaki-Nya akan berjejak di bukit Zaitun yang terletak di depan Yerusalem di sebelah timur. Bukit Zaitun itu akan terbelah dua dari timur ke barat, sehingga terjadi suatu lembah yang sangat besar; setengah dari bukit itu akan bergeser ke utara dan setengah lagi ke selatan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 5, 'Maka tertutuplah lembah gunung-gunung-Ku, sebab lembah gunung itu akan menyentuh sisinya; dan kamu akan melarikan diri seperti kamu pernah melarikan diri oleh karena gempa bumi pada zaman Uzia, raja Yehuda. Lalu TUHAN, Allahku, akan datang, dan semua orang kudus bersama-sama Dia.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 6, 'Maka pada waktu itu tidak akan ada lagi udara dingin atau keadaan beku,', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 7, 'tetapi akan ada satu hari?hari itu diketahui oleh TUHAN?dengan tidak ada pergantian siang dan malam, dan malampun menjadi siang.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 8, 'Pada waktu itu akan mengalir air kehidupan dari Yerusalem; setengahnya mengalir ke laut timur, dan setengah lagi mengalir ke laut barat; hal itu akan terus berlangsung dalam musim panas dan dalam musim dingin.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 9, 'Maka TUHAN akan menjadi Raja atas seluruh bumi; pada waktu itu TUHAN adalah satu-satunya dan nama-Nya satu-satunya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 10, 'Seluruh negeri ini akan berubah menjadi seperti Araba-Yordan, dari Geba sampai ke Rimon di sebelah selatan Yerusalem. Tetapi kota itu akan menjulang tinggi dan tetap tinggal di tempatnya, dari pintu gerbang Benyamin sampai ke tempat pintu gerbang yang dahulu, yakni sampai ke pintu gerbang Sudut, dan dari menara Hananeel sampai ke tempat pemerasan anggur raja.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 11, 'Orang akan menetap di dalamnya, sebab penumpasan tidak akan ada lagi, dan Yerusalem akan tetap aman.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 12, 'Inilah tulah yang akan ditimpakan TUHAN kepada segala bangsa yang memerangi Yerusalem: daging mereka akan menjadi busuk, sementara mereka masih berdiri, mata mereka akan menjadi busuk dalam lekuknya dan lidah mereka akan menjadi busuk dalam mulut mereka.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 13, 'Maka pada waktu itu akan terjadi kegemparan besar dari pada TUHAN di antara mereka, sehingga masing-masing memegang tangan temannya dan mengangkat tangannya melawan tangan temannya.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 14, 'Juga Yehuda akan berperang melawan Yerusalem itu; dan dikumpulkanlah harta benda segala bangsa di sekeliling, yaitu emas, perak dan pakaian dalam jumlah yang sangat besar.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 15, 'Tulah seperti itu juga akan menimpa kuda, bagal, unta, keledai dan segala hewan yang ada dalam perkemahan-perkemahan itu.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 16, 'Maka semua orang yang tinggal dari segala bangsa yang telah menyerang Yerusalem, akan datang tahun demi tahun untuk sujud menyembah kepada Raja, TUHAN semesta alam, dan untuk merayakan hari raya Pondok Daun.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 17, 'Tetapi bila mereka dari kaum-kaum di bumi tidak datang ke Yerusalem untuk sujud menyembah kepada Raja, TUHAN semesta alam, maka kepada mereka tidak akan turun hujan.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 18, 'Dan jika kaum Mesir tidak datang dan tidak masuk menghadap, maka kepada mereka akan turun tulah yang ditimpakan TUHAN kepada bangsa-bangsa yang tidak datang untuk merayakan hari raya Pondok Daun.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 19, 'Itulah hukuman dosa Mesir dan hukuman dosa segala bangsa yang tidak datang untuk merayakan hari raya Pondok Daun.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 20, 'Pada waktu itu akan tertulis pada kerencingan-kerencingan kuda: "Kudus bagi TUHAN!" dan kuali-kuali di rumah TUHAN akan seperti bokor-bokor penyiraman di depan mezbah.', 'id', 'TB'),
  ('38', 'za', 'Zakharia', 14, 21, 'Maka segala kuali di Yerusalem dan di Yehuda akan menjadi kudus bagi TUHAN semesta alam; semua orang yang mempersembahkan korban akan datang mengambilnya dan memasak di dalamnya. Dan tidak akan ada lagi pedagang di rumah TUHAN semesta alam pada waktu itu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 1, 'Ucapan ilahi. Firman TUHAN kepada Israel dengan perantaraan Maleakhi.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 2, '"Aku mengasihi kamu," firman TUHAN. Tetapi kamu berkata: "Dengan cara bagaimanakah Engkau mengasihi kami?" "Bukankah Esau itu kakak Yakub?" demikianlah firman TUHAN. "Namun Aku mengasihi Yakub,', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 3, 'tetapi membenci Esau. Sebab itu Aku membuat pegunungannya menjadi sunyi sepi dan tanah pusakanya Kujadikan padang gurun."', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 4, 'Apabila Edom berkata: "Kami telah hancur, tetapi kami akan membangun kembali reruntuhan itu," maka beginilah firman TUHAN semesta alam: "Mereka boleh membangun, tetapi Aku akan merobohkannya; dan orang akan menyebutkannya daerah kefasikan dan bangsa yang kepadanya TUHAN murka sampai selama-lamanya."', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 5, 'Matamu akan melihat dan kamu sendiri akan berkata: "TUHAN maha besar sampai di luar daerah Israel."', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 6, 'Seorang anak menghormati bapanya dan seorang hamba menghormati tuannya. Jika Aku ini bapa, di manakah hormat yang kepada-Ku itu? Jika Aku ini tuan, di manakah takut yang kepada-Ku itu? firman TUHAN semesta alam kepada kamu, hai para imam yang menghina nama-Ku. Tetapi kamu berkata: "Dengan cara bagaimanakah kami menghina nama-Mu?"', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 7, 'Kamu membawa roti cemar ke atas mezbah-Ku, tetapi berkata: "Dengan cara bagaimanakah kami mencemarkannya?" Dengan cara menyangka: "Meja TUHAN boleh dihinakan!"', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 8, 'Apabila kamu membawa seekor binatang buta untuk dipersembahkan, tidakkah itu jahat? Apabila kamu membawa binatang yang timpang dan sakit, tidakkah itu jahat? Cobalah menyampaikannya kepada bupatimu, apakah ia berkenan kepadamu, apalagi menyambut engkau dengan baik? firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 9, 'Maka sekarang: "Cobalah melunakkan hati Allah, supaya Ia mengasihani kita!" Oleh tangan kamulah terjadi hal itu, masakan Ia akan menyambut salah seorang dari padamu dengan baik? firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 10, 'Sekiranya ada di antara kamu yang mau menutup pintu, supaya jangan kamu menyalakan api di mezbah-Ku dengan percuma. Aku tidak suka kepada kamu, firman TUHAN semesta alam, dan Aku tidak berkenan menerima persembahan dari tanganmu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 11, 'Sebab dari terbitnya sampai kepada terbenamnya matahari nama-Ku besar di antara bangsa-bangsa, dan di setiap tempat dibakar dan dipersembahkan korban bagi nama-Ku dan juga korban sajian yang tahir; sebab nama-Ku besar di antara bangsa-bangsa, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 12, 'Tetapi kamu ini menajiskannya, karena kamu menyangka: "Meja Tuhan memang cemar dan makanan yang ada di situ boleh dihinakan!"', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 13, 'Kamu berkata: "Lihat, alangkah susah payahnya!" dan kamu menyusahkan Aku, firman TUHAN semesta alam. Kamu membawa binatang yang dirampas, binatang yang timpang dan binatang yang sakit, kamu membawanya sebagai persembahan. Akan berkenankah Aku menerimanya dari tanganmu? firman TUHAN.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 1, 14, 'Terkutuklah penipu, yang mempunyai seekor binatang jantan di antara kawanan ternaknya, yang dinazarkannya, tetapi ia mempersembahkan binatang yang cacat kepada Tuhan. Sebab Aku ini Raja yang besar, firman TUHAN semesta alam, dan nama-Ku ditakuti di antara bangsa-bangsa.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 1, 'Maka sekarang, kepada kamulah tertuju perintah ini, hai para imam!', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 2, 'Jika kamu tidak mendengarkan, dan jika kamu tidak memberi perhatian untuk menghormati nama-Ku, firman TUHAN semesta alam, maka Aku akan mengirimkan kutuk ke antaramu dan akan membuat berkat-berkatmu menjadi kutuk, dan Aku telah membuatnya menjadi kutuk, sebab kamu ini tidak memperhatikan.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 3, 'Sesungguhnya, Aku akan mematahkan lenganmu dan akan melemparkan kotoran ke mukamu, yakni kotoran korban dari hari-hari rayamu, dan orang akan menyeret kamu ke kotoran itu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 4, 'Maka kamu akan sadar, bahwa Kukirimkan perintah ini kepadamu, supaya perjanjian-Ku dengan Lewi tetap dipegang, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 5, 'Perjanjian-Ku dengan dia pada satu pihak ialah kehidupan dan sejahtera dan itu Kuberikan kepadanya?pada pihak lain ketakutan?dan ia takut kepada-Ku dan gentar terhadap nama-Ku.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 6, 'Pengajaran yang benar ada dalam mulutnya dan kecurangan tidak terdapat pada bibirnya. Dalam damai sejahtera dan kejujuran ia mengikuti Aku dan banyak orang dibuatnya berbalik dari pada kesalahan.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 7, 'Sebab bibir seorang imam memelihara pengetahuan dan orang mencari pengajaran dari mulutnya, sebab dialah utusan TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 8, 'Tetapi kamu ini menyimpang dari jalan; kamu membuat banyak orang tergelincir dengan pengajaranmu; kamu merusakkan perjanjian dengan Lewi, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 9, 'Maka Akupun akan membuat kamu hina dan rendah bagi seluruh umat ini, oleh karena kamu tidak mengikuti jalan yang Kutunjukkan, tetapi memandang bulu dalam pengajaranmu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 10, 'Bukankah kita sekalian mempunyai satu bapa? Bukankah satu Allah menciptakan kita? Lalu mengapa kita berkhianat satu sama lain dan dengan demikian menajiskan perjanjian nenek moyang kita?', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 11, 'Yehuda berkhianat, dan perbuatan keji dilakukan di Israel dan di Yerusalem, sebab Yehuda telah menajiskan tempat kudus yang dikasihi TUHAN dan telah menjadi suami anak perempuan allah asing.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 12, 'Biarlah TUHAN melenyapkan dari kemah-kemah Yakub segenap keturunan orang yang berbuat demikian, sekalipun ia membawa persembahan kepada TUHAN semesta alam!', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 13, 'Dan inilah yang kedua yang kamu lakukan: Kamu menutupi mezbah TUHAN dengan air mata, dengan tangisan dan rintihan, oleh karena Ia tidak lagi berpaling kepada persembahan dan tidak berkenan menerimanya dari tanganmu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 14, 'Dan kamu bertanya: "Oleh karena apa?" Oleh sebab TUHAN telah menjadi saksi antara engkau dan isteri masa mudamu yang kepadanya engkau telah tidak setia, padahal dialah teman sekutumu dan isteri seperjanjianmu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 15, 'Bukankah Allah yang Esa menjadikan mereka daging dan roh? Dan apakah yang dikehendaki kesatuan itu? Keturunan ilahi! Jadi jagalah dirimu! Dan janganlah orang tidak setia terhadap isteri dari masa mudanya.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 16, 'Sebab Aku membenci perceraian, firman TUHAN, Allah Israel?juga orang yang menutupi pakaiannya dengan kekerasan, firman TUHAN semesta alam. Maka jagalah dirimu dan janganlah berkhianat!', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 2, 17, 'Kamu menyusahi TUHAN dengan perkataanmu. Tetapi kamu berkata: "Dengan cara bagaimanakah kami menyusahi Dia?" Dengan cara kamu menyangka: "Setiap orang yang berbuat jahat adalah baik di mata TUHAN; kepada orang-orang yang demikianlah Ia berkenan?atau jika tidak, di manakah Allah yang menghukum?"', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 1, 'Lihat, Aku menyuruh utusan-Ku, supaya ia mempersiapkan jalan di hadapan-Ku! Dengan mendadak Tuhan yang kamu cari itu akan masuk ke bait-Nya! Malaikat Perjanjian yang kamu kehendaki itu, sesungguhnya, Ia datang, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 2, 'Siapakah yang dapat tahan akan hari kedatangan-Nya? Dan siapakah yang dapat tetap berdiri, apabila Ia menampakkan diri? Sebab Ia seperti api tukang pemurni logam dan seperti sabun tukang penatu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 3, 'Ia akan duduk seperti orang yang memurnikan dan mentahirkan perak; dan Ia mentahirkan orang Lewi, menyucikan mereka seperti emas dan seperti perak, supaya mereka menjadi orang-orang yang mempersembahkan korban yang benar kepada TUHAN.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 4, 'Maka persembahan Yehuda dan Yerusalem akan menyenangkan hati TUHAN seperti pada hari-hari dahulu kala dan seperti tahun-tahun yang sudah-sudah.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 5, 'Aku akan mendekati kamu untuk menghakimi dan akan segera menjadi saksi terhadap tukang-tukang sihir, orang-orang berzinah dan orang-orang yang bersumpah dusta dan terhadap orang-orang yang menindas orang upahan, janda dan anak piatu, dan yang mendesak ke samping orang asing, dengan tidak takut kepada-Ku, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 6, 'Bahwasanya Aku, TUHAN, tidak berubah, dan kamu, bani Yakub, tidak akan lenyap.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 7, 'Sejak zaman nenek moyangmu kamu telah menyimpang dari ketetapan-Ku dan tidak memeliharanya. Kembalilah kepada-Ku, maka Aku akan kembali kepadamu, firman TUHAN semesta alam. Tetapi kamu berkata: "Dengan cara bagaimanakah kami harus kembali?"', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 8, 'Bolehkah manusia menipu Allah? Namun kamu menipu Aku. Tetapi kamu berkata: "Dengan cara bagaimanakah kami menipu Engkau?" Mengenai persembahan persepuluhan dan persembahan khusus!', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 9, 'Kamu telah kena kutuk, tetapi kamu masih menipu Aku, ya kamu seluruh bangsa!', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 10, 'Bawalah seluruh persembahan persepuluhan itu ke dalam rumah perbendaharaan, supaya ada persediaan makanan di rumah-Ku dan ujilah Aku, firman TUHAN semesta alam, apakah Aku tidak membukakan bagimu tingkap-tingkap langit dan mencurahkan berkat kepadamu sampai berkelimpahan.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 11, 'Aku akan menghardik bagimu belalang pelahap, supaya jangan dihabisinya hasil tanahmu dan supaya jangan pohon anggur di padang tidak berbuah bagimu, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 12, 'Maka segala bangsa akan menyebut kamu berbahagia, sebab kamu ini akan menjadi negeri kesukaan, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 13, 'Bicaramu kurang ajar tentang Aku, firman TUHAN. Tetapi kamu berkata: "Apakah kami bicarakan di antara kami tentang Engkau?"', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 14, 'Kamu berkata: "Adalah sia-sia beribadah kepada Allah. Apakah untungnya kita memelihara apa yang harus dilakukan terhadap-Nya dan berjalan dengan pakaian berkabung di hadapan TUHAN semesta alam?', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 15, 'Oleh sebab itu kita ini menyebut berbahagia orang-orang yang gegabah: bukan saja mujur orang-orang yang berbuat fasik itu, tetapi dengan mencobai Allahpun, mereka luput juga."', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 16, 'Beginilah berbicara satu sama lain orang-orang yang takut akan TUHAN: "TUHAN memperhatikan dan mendengarnya; sebuah kitab peringatan ditulis di hadapan-Nya bagi orang-orang yang takut akan TUHAN dan bagi orang-orang yang menghormati nama-Nya."', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 17, 'Mereka akan menjadi milik kesayangan-Ku sendiri, firman TUHAN semesta alam, pada hari yang Kusiapkan. Aku akan mengasihani mereka sama seperti seseorang menyayangi anaknya yang melayani dia.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 3, 18, 'Maka kamu akan melihat kembali perbedaan antara orang benar dan orang fasik, antara orang yang beribadah kepada Allah dan orang yang tidak beribadah kepada-Nya.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 4, 1, 'Bahwa sesungguhnya hari itu datang, menyala seperti perapian, maka semua orang gegabah dan setiap orang yang berbuat fasik menjadi seperti jerami dan akan terbakar oleh hari yang datang itu, firman TUHAN semesta alam, sampai tidak ditinggalkannya akar dan cabang mereka.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 4, 2, 'Tetapi kamu yang takut akan nama-Ku, bagimu akan terbit surya kebenaran dengan kesembuhan pada sayapnya. Kamu akan keluar dan berjingkrak-jingkrak seperti anak lembu lepas kandang.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 4, 3, 'Kamu akan menginjak-injak orang-orang fasik, sebab mereka akan menjadi abu di bawah telapak kakimu, pada hari yang Kusiapkan itu, firman TUHAN semesta alam.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 4, 4, 'Ingatlah kepada Taurat yang telah Kuperintahkan kepada Musa, hamba-Ku, di gunung Horeb untuk disampaikan kepada seluruh Israel, yakni ketetapan-ketetapan dan hukum-hukum.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 4, 5, 'Sesungguhnya Aku akan mengutus nabi Elia kepadamu menjelang datangnya hari TUHAN yang besar dan dahsyat itu.', 'id', 'TB'),
  ('39', 'mal', 'Maleakhi', 4, 6, 'Maka ia akan membuat hati bapa-bapa berbalik kepada anak-anaknya dan hati anak-anak kepada bapa-bapanya supaya jangan Aku datang memukul bumi sehingga musnah.', 'id', 'TB')
